{
  "name": "grand-theft-block",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0",
    "build": "vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^7.1.0"
  }
}

/* ============================================================
   GRAND THEFT BLOCK — UI
   ============================================================ */
:root {
  --ink: #07080b;
  --ink-2: #0d1015;
  --panel: rgba(10, 12, 17, 0.78);
  --panel-solid: #0d1015;
  --line: rgba(255, 255, 255, 0.14);
  --gold: #ffc72c;
  --gold-2: #ffe08a;
  --green: #72e08a;
  --red: #ff4b4b;
  --blue: #57b7ff;
  --white: #f5f7fb;
  --muted: #9aa3b2;
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0; padding: 0; width: 100%; height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--white);
  font-family: "Arial Narrow", "Roboto Condensed", "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

body { overscroll-behavior: none; }
canvas { display: block; }
button, input { font-family: inherit; }
.hidden { display: none !important; }

#app {
  position: fixed; inset: 0;
  width: 100%; height: 100%;
  overflow: hidden;
  background: #08090c;
}

#game {
  position: absolute; inset: 0;
  width: 100%; height: 100%;
  outline: none;
  cursor: crosshair;
}

#fade {
  position: absolute; inset: 0;
  background: #000;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s linear;
  z-index: 80;
}
#fade.on { opacity: 1; }

#vignette {
  position: absolute; inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at center, transparent 55%, rgba(0,0,0,0.42) 100%),
    linear-gradient(to bottom, rgba(0,0,0,0.32), transparent 14%, transparent 80%, rgba(0,0,0,0.38));
  z-index: 4;
}

/* ============================================================
   HUD
   ============================================================ */
#hud {
  position: absolute; inset: 0;
  pointer-events: none;
  z-index: 20;
  font-size: 13px;
  letter-spacing: 0.08em;
}

.hud-corner { position: absolute; top: calc(18px + var(--safe-t)); }
#hud-top-left { left: calc(24px + var(--safe-l)); }
#hud-top-right { right: calc(24px + var(--safe-r)); text-align: right; }

#location-line {
  display: flex; align-items: center; gap: 9px;
  font-weight: 900; font-size: 17px; letter-spacing: 0.18em;
  text-shadow: 0 2px 0 #000, 0 0 16px rgba(0,0,0,.8);
}
.map-pin {
  width: 9px; height: 9px; display: inline-block;
  background: var(--gold);
  clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
  box-shadow: 0 0 9px var(--gold);
}
#seed-line {
  margin-top: 5px; color: var(--muted); font-size: 10px; letter-spacing: 0.2em;
}
#seed-line b { color: var(--gold-2); font-weight: 700; letter-spacing: 0.12em; }

#wanted-row { height: 24px; display: flex; justify-content: flex-end; gap: 3px; }
.star {
  font-size: 22px; line-height: 24px; color: rgba(255,255,255,0.16);
  text-shadow: 0 1px 0 #000;
  transition: color .15s, transform .15s, filter .15s;
}
.star.on { color: var(--gold); filter: drop-shadow(0 0 7px rgba(255,199,44,.8)); }
.star.pulse { animation: starPulse .6s infinite alternate; }
@keyframes starPulse { from { transform: scale(1); } to { transform: scale(1.18); } }

#cash-row {
  margin-top: 2px;
  font-size: 26px; font-weight: 900; letter-spacing: 0.03em;
  color: var(--green);
  text-shadow: 0 2px 0 rgba(0,0,0,.85), 0 0 20px rgba(114,224,138,.25);
}
.cash-label { font-size: 10px; color: var(--muted); margin-right: 8px; letter-spacing: .22em; vertical-align: middle; }
#clock-row { color: var(--muted); font-size: 11px; letter-spacing: .18em; margin-top: 1px; }
#clock { color: var(--white); font-weight: 700; margin-right: 8px; }

#minimap-wrap {
  position: absolute;
  left: calc(22px + var(--safe-l));
  bottom: calc(22px + var(--safe-b));
  width: 186px; height: 186px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid rgba(245,247,251,0.55);
  background: #16211b;
  box-shadow: 0 8px 34px rgba(0,0,0,.65), inset 0 0 30px rgba(0,0,0,.45);
}
#minimap { width: 100%; height: 100%; }
#minimap-ring {
  position: absolute; inset: 0; border-radius: 50%;
  box-shadow: inset 0 0 0 4px rgba(7,8,11,0.58), inset 0 0 22px rgba(0,0,0,.55);
  pointer-events: none;
}
#minimap-n {
  position: absolute; top: 3px; left: 50%; transform: translateX(-50%);
  font-size: 10px; font-weight: 900; color: var(--white); z-index: 2;
  background: rgba(0,0,0,.6); border-radius: 3px; padding: 0 4px;
}

#status-bars {
  position: absolute;
  left: calc(230px + var(--safe-l));
  bottom: calc(30px + var(--safe-b));
  width: 240px;
  display: flex; flex-direction: column; gap: 7px;
  text-shadow: 0 1px 2px #000;
}
.stat-row { display: flex; align-items: center; gap: 8px; }
.stat-icon {
  width: 20px; height: 20px; flex: 0 0 20px;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; font-weight: 900;
  border: 1px solid rgba(255,255,255,.16);
  background: rgba(0,0,0,.4);
}
.health-icon { color: var(--red); }
.armor-icon { color: var(--blue); }
.weapon-icon { color: var(--gold); }
.bar-shell {
  height: 11px; flex: 1;
  background: rgba(0,0,0,.55);
  border: 1px solid rgba(255,255,255,.12);
  transform: skewX(-14deg);
  overflow: hidden;
  padding: 2px;
}
.bar { height: 100%; width: 100%; transition: width .18s ease; }
.bar.health { background: linear-gradient(90deg, #d92c2c, #ff6a5e); box-shadow: 0 0 10px rgba(255,75,75,.4); }
.bar.armor { background: linear-gradient(90deg, #2a6fd4, #6cc7ff); box-shadow: 0 0 10px rgba(87,183,255,.35); }
.stat-num { width: 26px; text-align: right; font-size: 11px; color: var(--muted); font-weight: 700; }
.weapon-row {
  margin-top: 2px; font-size: 11px; color: var(--muted);
  letter-spacing: .18em;
}
#weapon-name { flex: 1; color: var(--white); font-weight: 700; }
#ammo { color: var(--gold-2); font-weight: 700; letter-spacing: .1em; }

#vehicle-panel {
  position: absolute; right: calc(28px + var(--safe-r)); bottom: calc(26px + var(--safe-b));
  width: 190px; text-align: right;
  filter: drop-shadow(0 4px 10px rgba(0,0,0,.6));
}
#speed-num {
  font-size: 52px; line-height: 0.9; font-weight: 900; letter-spacing: -0.04em;
  color: var(--white);
  text-shadow: 0 3px 0 #000;
}
#speed-unit { font-size: 10px; letter-spacing: .28em; color: var(--gold); margin-top: 2px; }
#speed-bar-shell {
  height: 7px; margin-top: 7px; background: rgba(0,0,0,.6);
  border: 1px solid rgba(255,255,255,.18); transform: skewX(-18deg);
  overflow: hidden;
}
#speed-bar { height: 100%; width: 0%; background: linear-gradient(90deg, var(--gold), #ff8a3c); }
#gear { font-size: 11px; letter-spacing: .2em; color: var(--muted); margin-top: 4px; }

#crosshair {
  position: absolute; left: 50%; top: 50%;
  width: 26px; height: 26px; transform: translate(-50%, -50%);
  opacity: .82;
}
#crosshair i {
  position: absolute; background: rgba(255,255,255,.9);
  box-shadow: 0 0 2px #000;
}
#crosshair i:nth-child(1) { left: 12px; top: 0; width: 2px; height: 7px; }
#crosshair i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 7px; }
#crosshair i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 7px; }
#crosshair i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 7px; }
#crosshair b {
  position: absolute; left: 11px; top: 11px; width: 4px; height: 4px;
  background: var(--gold); border-radius: 50%; box-shadow: 0 0 6px var(--gold);
}
#crosshair.aiming i { background: var(--red); }

#prompt {
  position: absolute; left: 50%; bottom: calc(168px + var(--safe-b));
  transform: translateX(-50%);
  background: rgba(8,9,12,.84);
  border: 1px solid rgba(255,199,44,.45);
  border-left: 4px solid var(--gold);
  padding: 9px 17px;
  font-size: 12px; letter-spacing: .14em; font-weight: 700;
  white-space: nowrap;
  box-shadow: 0 6px 24px rgba(0,0,0,.5);
  animation: promptIn .16s ease-out;
}
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 5px); } }
#prompt .key, .key {
  display: inline-block;
  min-width: 19px; text-align: center;
  padding: 2px 5px; margin: 0 2px;
  background: var(--white); color: var(--ink);
  border-radius: 2px;
  font-weight: 900; font-size: 10px;
  box-shadow: 0 2px 0 #9aa3b2;
}

#notifications {
  position: absolute; right: calc(26px + var(--safe-r)); top: calc(122px + var(--safe-t));
  display: flex; flex-direction: column; align-items: flex-end; gap: 6px;
  width: 320px;
}
.toast {
  background: linear-gradient(90deg, rgba(8,9,12,0), rgba(8,9,12,.88) 12%);
  border-right: 3px solid var(--gold);
  padding: 8px 13px 8px 28px;
  text-align: right;
  font-size: 11px; letter-spacing: .1em;
  animation: toastIn .22s ease-out, toastOut .4s ease-in forwards 4.2s;
  max-width: 100%;
}
.toast b { color: var(--gold); font-weight: 900; display: block; font-size: 12px; letter-spacing: .12em; }
.toast.good { border-color: var(--green); }
.toast.good b { color: var(--green); }
.toast.bad { border-color: var(--red); }
.toast.bad b { color: var(--red); }
@keyframes toastIn { from { opacity: 0; transform: translateX(22px); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(16px); } }

#mission-box {
  position: absolute; right: calc(24px + var(--safe-r)); top: calc(150px + var(--safe-t));
  width: 300px;
  padding: 12px 16px;
  background: rgba(8,9,12,.72);
  border-top: 2px solid var(--gold);
  border-bottom: 1px solid rgba(255,255,255,.1);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}
#mission-kicker { font-size: 9px; letter-spacing: .3em; color: var(--gold); font-weight: 900; }
#mission-title { font-size: 16px; font-weight: 900; letter-spacing: .08em; margin: 3px 0 5px; }
#mission-objective { font-size: 11px; color: var(--muted); line-height: 1.45; letter-spacing: .05em; }
#mission-timer { margin-top: 7px; font-size: 13px; font-weight: 900; color: var(--gold-2); letter-spacing: .1em; }

#big-banner {
  position: absolute; left: 50%; top: 19%; transform: translateX(-50%);
  text-align: center;
  animation: bannerIn .5s ease-out, bannerOut .7s ease-in forwards 3.3s;
  text-shadow: 0 3px 0 rgba(0,0,0,.8);
}
#big-banner-title { font-size: 44px; font-weight: 900; letter-spacing: .22em; color: var(--white); }
#big-banner-sub { font-size: 12px; letter-spacing: .5em; color: var(--gold); margin-top: 2px; }
@keyframes bannerIn { from { opacity: 0; transform: translate(-50%, 12px); } }
@keyframes bannerOut { to { opacity: 0; } }

#hint {
  position: absolute; right: calc(26px + var(--safe-r)); bottom: calc(150px + var(--safe-b));
  font-size: 9px; letter-spacing: .14em; color: rgba(255,255,255,.45);
  display: flex; gap: 9px; align-items: center; flex-wrap: wrap; justify-content: flex-end;
  max-width: 370px;
}
#hint .key { font-size: 8px; padding: 1px 4px; min-width: 16px; opacity: .8; }

/* ============================================================
   START SCREEN
   ============================================================ */
#start-screen {
  position: absolute; inset: 0; z-index: 60;
  display: flex; flex-direction: column; justify-content: space-between;
  padding: calc(26px + var(--safe-t)) calc(34px + var(--safe-r)) calc(22px + var(--safe-b)) calc(34px + var(--safe-l));
  background:
    linear-gradient(90deg, rgba(4,5,8,.92) 0%, rgba(4,5,8,.55) 42%, rgba(4,5,8,.24) 68%, rgba(4,5,8,.7) 100%),
    linear-gradient(to top, rgba(4,5,8,.96), transparent 42%);
  transition: opacity .4s ease, visibility .4s;
}
#start-screen.closing { opacity: 0; visibility: hidden; }

.start-top { display: flex; justify-content: space-between; align-items: center; }
.brand-chip, .build-chip {
  font-size: 9px; letter-spacing: .24em; font-weight: 700; color: rgba(255,255,255,.6);
  border: 1px solid rgba(255,255,255,.2);
  padding: 6px 11px; background: rgba(0,0,0,.32);
  display: flex; align-items: center; gap: 8px;
}
.brand-dot { width: 7px; height: 7px; background: var(--gold); border-radius: 50%; box-shadow: 0 0 10px var(--gold); }
.build-chip { color: var(--gold); }

.start-main {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 30px;
  padding-bottom: 4vh;
}
.logo-block { max-width: 720px; text-shadow: 0 6px 24px rgba(0,0,0,.7); }
.logo-kicker {
  font-size: 11px; letter-spacing: .44em; color: var(--gold); font-weight: 900;
  margin: 0 0 7px 5px;
}
.logo { margin: 0; font-weight: 900; line-height: .82; letter-spacing: -.035em; }
.logo-line1 { display: block; font-size: clamp(48px, 7.4vw, 118px); color: var(--white); }
.logo-line2 {
  display: block; font-size: clamp(70px, 11.4vw, 180px); color: var(--gold);
  -webkit-text-stroke: 2px rgba(0,0,0,.3);
  text-shadow: 5px 5px 0 rgba(0,0,0,.42), 0 0 60px rgba(255,199,44,.2);
  letter-spacing: -.02em;
}
.logo-tag {
  font-size: 11px; letter-spacing: .2em; color: rgba(255,255,255,.66);
  margin-top: 19px; max-width: 520px; line-height: 1.7;
}

.seed-card {
  width: 378px; flex: 0 0 378px;
  background: rgba(8,10,14,.82);
  border: 1px solid rgba(255,255,255,.16);
  border-top: 3px solid var(--gold);
  padding: 20px 20px 16px;
  backdrop-filter: blur(10px);
