// Deterministic seeded random + noise utilities.
// Everything the world generator consumes flows through these, so a seed string
// always produces the exact same county.

export function hashString(str) {
  let h = 2166136261 >>> 0;
  const s = String(str);
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  h = Math.imul(h, 3266489909);
  h ^= h >>> 16;
  return h >>> 0;
}

export function mulberry32(a) {
  let t = a >>> 0;
  return function () {
    t = (t + 0x6d2b79f5) >>> 0;
    let r = t;
    r = Math.imul(r ^ (r >>> 15), r | 1);
    r ^= r + Math.imul(r ^ (r >>> 7), r | 61);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

/** Named deterministic stream so adding a new system can't shift another. */
export function stream(seed, name) {
  const h = (hashString(String(seed)) ^ hashString(String(name)) ^ 0x9e3779b9) >>> 0;
  const rng = mulberry32(h);
  rng.int = (min, max) => Math.floor(rng() * (max - min + 1)) + min;
  rng.range = (min, max) => min + rng() * (max - min);
  rng.pick = (arr) => arr[Math.floor(rng() * arr.length)];
  rng.chance = (p) => rng() < p;
  rng.sign = () => (rng() < 0.5 ? -1 : 1);
  return rng;
}

function hash2i(x, y, seed) {
  let h = (seed ^ Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263)) >>> 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967295;
}

function fade(t) { return t * t * t * (t * (t * 6 - 15) + 10); }
function lerp(a, b, t) { return a + (b - a) * t; }

/** Smooth value noise in [-1, 1]. */
export function noise2(x, y, seed = 0) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = fade(xf), v = fade(yf);
  const a = hash2i(xi, yi, seed);
  const b = hash2i(xi + 1, yi, seed);
  const c = hash2i(xi, yi + 1, seed);
  const d = hash2i(xi + 1, yi + 1, seed);
  return lerp(lerp(a, b, u), lerp(c, d, u), v) * 2 - 1;
}

/** Fractal brownian motion. */
export function fbm2(x, y, seed = 0, octaves = 4, lacunarity = 2.02, gain = 0.5) {
  let amp = 1, freq = 1, sum = 0, norm = 0;
  for (let i = 0; i < octaves; i++) {
    sum += noise2(x * freq, y * freq, (seed + i * 1013) >>> 0) * amp;
    norm += amp;
    amp *= gain;
    freq *= lacunarity;
  }
  return sum / norm;
}

/** Cellular-ish ridge noise for mountain spines. */
export function ridge2(x, y, seed = 0, octaves = 4) {
  let amp = 1, freq = 1, sum = 0, norm = 0;
  for (let i = 0; i < octaves; i++) {
    const n = 1 - Math.abs(noise2(x * freq, y * freq, (seed + 711 * i) >>> 0));
    sum += n * n * amp;
    norm += amp;
    amp *= 0.52;
    freq *= 2.03;
  }
  return sum / norm;
}

/** Stable per-cell hash in [0,1). */
export function hashCell(x, y, seed = 0) {
  return hash2i(x, y, seed);
}

export function smoothstep(edge0, edge1, x) {
  const t = Math.min(1, Math.max(0, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

export function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
export function lerpN(a, b, t) { return a + (b - a) * t; }

export function formatSeed(seed) {
  return String(seed).trim().toLowerCase().replace(/\s+/g, '-').slice(0, 32) || 'san-voxel';
}

export function randomSeed() {
  const a = ['vice', 'sand', 'neon', 'rust', 'palm', 'dust', 'coral', 'iron', 'sunset', 'bay', 'grape', 'cactus', 'crown', 'pixel', 'harbor', 'delta', 'ghost', 'amber', 'chrome', 'dune'];
  const b = ['beach', 'heights', 'hills', 'grove', 'city', 'county', 'coast', 'bluff', 'mirage', 'project', 'strip', 'canyon', 'port', 'vale', 'springs', 'row'];
  const r = mulberry32((Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0);
  return `${a[Math.floor(r() * a.length)]}-${b[Math.floor(r() * b.length)]}-${Math.floor(r() * 900 + 100)}`;
}

import * as THREE from 'three';
import { mulberry32 } from './rng.js';

/** Tiny grayscale pixel texture used by terrain + roads (tinted by vertex colors). */
export function makeNoiseTexture() {
  const size = 32;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const img = ctx.createImageData(size, size);
  const rng = mulberry32(0xb10c);
  for (let i = 0; i < size * size; i++) {
    let v = 176 + Math.floor(rng() * 64);
    if (rng() < 0.09) v = 148 + Math.floor(rng() * 30);
    img.data[i * 4] = v;
    img.data[i * 4 + 1] = v;
    img.data[i * 4 + 2] = v;
    img.data[i * 4 + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestMipmapNearestFilter;
  tex.anisotropy = 4;
  return tex;
}

function shade(hex, amount) {
  const c = new THREE.Color(hex);
  c.offsetHSL(0, 0, amount);
  return '#' + c.getHexString();
}

/**
 * Facade style: wall texture + matching emissive map. Windows are pixel art.
 * Returns maps sized so one tile represents TILE_WORLD units.
 */
export function makeFacadeMaps(style, variant = 0) {
  const S = 128;
  const tile = 32;
  const c = document.createElement('canvas');
  c.width = c.height = S;
  const ctx = c.getContext('2d');
  const e = document.createElement('canvas');
  e.width = e.height = S;
  const ectx = e.getContext('2d');
  const rng = mulberry32(0xfacade + variant * 7717 + style.wall.length * 31);

  ctx.fillStyle = style.wall;
  ctx.fillRect(0, 0, S, S);
  ectx.fillStyle = '#000';
  ectx.fillRect(0, 0, S, S);

  // subtle pixel grime
  for (let i = 0; i < 700; i++) {
    const x = Math.floor(rng() * S), y = Math.floor(rng() * S);
    ctx.fillStyle = rng() < 0.5 ? 'rgba(0,0,0,0.07)' : 'rgba(255,255,255,0.05)';
    ctx.fillRect(x, y, 1, 1);
  }

  if (style.brick) {
    ctx.strokeStyle = 'rgba(0,0,0,0.18)';
    ctx.lineWidth = 1;
    for (let y = 0; y < S; y += 8) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(S, y); ctx.stroke();
    }
  }

  const cols = style.cols || 4;
  const rows = style.rows || 4;
  const cw = S / cols, ch = S / rows;
  for (let ry = 0; ry < rows; ry++) {
    for (let rx = 0; rx < cols; rx++) {
      const x = rx * cw, y = ry * ch;
      const wm = style.glass ? 4 : 8;
      const wx = x + wm, wy = y + (style.glass ? 4 : 7);
      const ww = cw - wm * 2, wh = ch - (style.glass ? 8 : 15);
      // frame
      ctx.fillStyle = style.frame || '#2a2d33';
      ctx.fillRect(wx - 2, wy - 2, ww + 4, wh + 4);
      // glass gradient-ish
      const grd = ctx.createLinearGradient(wx, wy, wx + ww, wy + wh);
      grd.addColorStop(0, style.glassTop || '#3d5d73');
      grd.addColorStop(0.55, style.glassMid || '#2b4356');
      grd.addColorStop(1, style.glassBot || '#1a2b38');
      ctx.fillStyle = grd;
      ctx.fillRect(wx, wy, ww, wh);
      // mullion
      ctx.fillStyle = 'rgba(20,25,30,0.55)';
      ctx.fillRect(wx + ww / 2 - 1, wy, 2, wh);
      if (rng() < style.litChance) {
        const warm = rng() < 0.8;
        ectx.fillStyle = warm ? (rng() < 0.3 ? '#ffd07a' : '#ffb84d') : '#a9d8ff';
        ectx.fillRect(wx, wy, ww, wh);
        if (rng() < 0.3) {
          ectx.fillStyle = 'rgba(0,0,0,0.45)';
          ectx.fillRect(wx, wy + wh * 0.62, ww, wh * 0.38);
        }
      }
      // sill
      ctx.fillStyle = shade(style.wall, style.dark ? 0.08 : -0.1);
      ctx.fillRect(wx - 3, wy + wh + 2, ww + 6, 2);
    }
  }
  if (style.band) {
    ctx.fillStyle = style.band;
    for (let y = 0; y < S; y += S / 4) ctx.fillRect(0, y, S, 2);
  }

  const map = new THREE.CanvasTexture(c);
  map.wrapS = map.wrapT = THREE.RepeatWrapping;
  map.magFilter = THREE.NearestFilter;
  map.minFilter = THREE.NearestMipmapNearestFilter;
  map.colorSpace = THREE.SRGBColorSpace;
  map.anisotropy = 4;

  const emissiveMap = new THREE.CanvasTexture(e);
  emissiveMap.wrapS = emissiveMap.wrapT = THREE.RepeatWrapping;
  emissiveMap.magFilter = THREE.NearestFilter;
  emissiveMap.minFilter = THREE.NearestMipmapNearestFilter;
  emissiveMap.colorSpace = THREE.SRGBColorSpace;

  return { map, emissiveMap, tileWorld: 7.2 };
}

export function makeGlowTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.25, 'rgba(255,245,200,0.8)');
  g.addColorStop(0.6, 'rgba(255,220,120,0.18)');
  g.addColorStop(1, 'rgba(255,220,120,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function makeStarTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 8;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#fff';
  ctx.fillRect(3, 0, 2, 8);
  ctx.fillRect(0, 3, 8, 2);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function makeWaterNormal() {
  // small tileable normal-ish pattern (used as a bump map)
  const S = 64;
  const c = document.createElement('canvas');
  c.width = c.height = S;
  const ctx = c.getContext('2d');
  const img = ctx.createImageData(S, S);
  const rng = mulberry32(0xwater);
  for (let y = 0; y < S; y++) {
    for (let x = 0; x < S; x++) {
      const nx = Math.sin((x / S) * Math.PI * 4 + Math.sin(y * 0.2) * 2);
      const ny = Math.cos((y / S) * Math.PI * 4 + Math.cos(x * 0.17) * 2);
      const i = (y * S + x) * 4;
      img.data[i] = 128 + nx * 42 + (rng() - 0.5) * 10;
      img.data[i + 1] = 128 + ny * 42 + (rng() - 0.5) * 10;
      img.data[i + 2] = 255;
      img.data[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(10, 10);
  return tex;
}

