import * as THREE from 'three';
import { stream, clamp, smoothstep } from '../rng.js';
import { SEA_LEVEL } from './height.js';

const DAY_LENGTH = 600; // seconds for a full 24h cycle

const C = {
  dayTop: new THREE.Color(0x3f7fbe),
  dayBot: new THREE.Color(0xc9e0ea),
  duskTop: new THREE.Color(0x3a2f5e),
  duskBot: new THREE.Color(0xf08b4a),
  nightTop: new THREE.Color(0x04060d),
  nightBot: new THREE.Color(0x111a2a),
  fogDay: new THREE.Color(0xb9d4e2),
  fogDusk: new THREE.Color(0xd98b62),
  fogNight: new THREE.Color(0x0a101c),
};

export class Environment {
  constructor(scene, seed, city, noiseTex, renderer) {
    this.scene = scene;
    this.seed = seed;
    this.city = city;
    this.renderer = renderer;
    this.dayTime = 0.335;
    this.nightFactor = 0;
    this.sunDir = new THREE.Vector3();
    this.moonDir = new THREE.Vector3();
    this.lightDir = new THREE.Vector3();
    this.time = 0;

    scene.background = new THREE.Color(0x9fc6da);
    scene.fog = new THREE.Fog(0xb9d4e2, 150, 430);

    // ---------------- sky dome ----------------
    this.skyUniforms = {
      topColor: { value: C.dayTop.clone() },
      bottomColor: { value: C.dayBot.clone() },
      sunColor: { value: new THREE.Color(0xfff1c4) },
      sunDir: { value: new THREE.Vector3(0.5, 0.5, 0.3) },
      nightMix: { value: 0 },
    };
    const skyMat = new THREE.ShaderMaterial({
      uniforms: this.skyUniforms,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform vec3 topColor;
        uniform vec3 bottomColor;
        uniform vec3 sunColor;
        uniform vec3 sunDir;
        uniform float nightMix;
        varying vec3 vDir;
        void main() {
          float h = clamp(vDir.y, -0.08, 1.0);
          vec3 col = mix(bottomColor, topColor, smoothstep(-0.02, 0.62, h));
          float sunAmt = max(dot(vDir, normalize(sunDir)), 0.0);
          float disc = pow(sunAmt, 1500.0) * 2.0;
          float glow = pow(sunAmt, 18.0) * 0.32;
          col += sunColor * (disc + glow) * (1.0 - nightMix * 0.75);
          float horizon = exp(-abs(h) * 12.0);
          col += bottomColor * horizon * 0.16;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    this.sky = new THREE.Mesh(new THREE.SphereGeometry(900, 32, 20), skyMat);
    this.sky.frustumCulled = false;
    this.sky.renderOrder = -100;
    scene.add(this.sky);

    // ---------------- stars ----------------
    const starGeo = new THREE.BufferGeometry();
    const starPos = [];
    const srng = stream(seed, 'stars');
    for (let i = 0; i < 700; i++) {
      const a = srng() * Math.PI * 2;
      const y = srng();
      const r = 820;
      const rr = Math.sqrt(1 - y * y);
      starPos.push(Math.cos(a) * rr * r, y * r * 0.9 + 40, Math.sin(a) * rr * r);
    }
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
    this.starMat = new THREE.PointsMaterial({
      color: 0xdfe8ff, size: 2.4, sizeAttenuation: false,
      transparent: true, opacity: 0, depthWrite: false, fog: false,
    });
    this.stars = new THREE.Points(starGeo, this.starMat);
    this.stars.frustumCulled = false;
    this.stars.renderOrder = -90;
    scene.add(this.stars);

    // ---------------- moon ----------------
    this.moonMat = new THREE.MeshBasicMaterial({ color: 0xe6ecff, fog: false });
    this.moon = new THREE.Mesh(new THREE.SphereGeometry(13, 16, 12), this.moonMat);
    this.moon.frustumCulled = false;
    this.moon.renderOrder = -85;
    scene.add(this.moon);

    // ---------------- clouds ----------------
    this.cloudMat = new THREE.MeshLambertMaterial({
      color: 0xffffff, transparent: true, opacity: 0.86,
      fog: false, depthWrite: false,
    });
    const cloudGeo = new THREE.BoxGeometry(1, 1, 1);
    const crng = stream(seed, 'clouds');
    const count = 110;
    this.clouds = new THREE.InstancedMesh(cloudGeo, this.cloudMat, count);
    this.clouds.frustumCulled = false;
    this.cloudData = [];
    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const s = new THREE.Vector3();
    const p = new THREE.Vector3();
    for (let i = 0; i < count; i++) {
      const w = crng.range(10, 44);
      const d = crng.range(8, 30);
      const h = crng.range(2.5, 7);
      p.set(crng.range(-700, 700), crng.range(105, 155), crng.range(-700, 700));
      s.set(w, h, d);
      m.compose(p, q, s);
      this.clouds.setMatrixAt(i, m);
      this.cloudData.push({ x: p.x, y: p.y, z: p.z, s: s.clone() });
    }
    this.clouds.instanceMatrix.needsUpdate = true;
    this.clouds.renderOrder = -80;
    scene.add(this.clouds);

    // ---------------- ocean ----------------
    this.waterTex = noiseTex.clone();
    this.waterTex.needsUpdate = true;
    this.waterTex.wrapS = this.waterTex.wrapT = THREE.RepeatWrapping;
    this.waterTex.repeat.set(48, 48);
    this.waterMat = new THREE.MeshPhongMaterial({
      color: 0x2f7da5,
      map: this.waterTex,
      transparent: true,
      opacity: 0.8,
      shininess: 90,
      specular: 0xbfe6ff,
      depthWrite: false,
    });
    const waterGeo = new THREE.PlaneGeometry(3600, 3600, 1, 1);
    this.water = new THREE.Mesh(waterGeo, this.waterMat);
    this.water.rotation.x = -Math.PI / 2;
    this.water.position.y = SEA_LEVEL + 0.02;
    this.water.renderOrder = 2;
    this.water.receiveShadow = false;
    scene.add(this.water);

    // ---------------- lights ----------------
    this.hemi = new THREE.HemisphereLight(0xbfd9ea, 0x4a463d, 0.85);
    scene.add(this.hemi);
    this.ambient = new THREE.AmbientLight(0xffffff, 0.17);
    scene.add(this.ambient);

    this.sun = new THREE.DirectionalLight(0xfff2d8, 2.0);
    this.sun.castShadow = true;
    this.sun.shadow.mapSize.set(1024, 1024);
    this.sun.shadow.camera.left = -95;
    this.sun.shadow.camera.right = 95;
    this.sun.shadow.camera.top = 95;
    this.sun.shadow.camera.bottom = -95;
    this.sun.shadow.camera.near = 1;
    this.sun.shadow.camera.far = 320;
    this.sun.shadow.bias = -0.0005;
    this.sun.shadow.normalBias = 0.035;
    scene.add(this.sun);
    this.sunTarget = new THREE.Object3D();
    scene.add(this.sunTarget);
    this.sun.target = this.sunTarget;

    this._facadeMats = [];
    this._lampMat = null;
    this._fountainMats = [];
    this.shadowsEnabled = true;
  }

  setCityMaterials(facadeMats, lampMat) {
    this._facadeMats = facadeMats || [];
    this._lampMat = lampMat;
  }

  setShadows(enabled) {
    this.shadowsEnabled = enabled;
    this.sun.castShadow = enabled;
  }

  update(dt, camera, playerPos) {
    this.time += dt;
    this.dayTime = (this.dayTime + dt / DAY_LENGTH) % 1;

    const ang = (this.dayTime - 0.25) * Math.PI * 2;
    this.sunDir.set(Math.cos(ang), Math.sin(ang), 0.34).normalize();
    this.moonDir.set(-Math.cos(ang), -Math.sin(ang), -0.28).normalize();

    const sy = this.sunDir.y;
    const dayF = smoothstep(-0.06, 0.24, sy);
    const duskF = Math.max(0, 1 - Math.abs(sy) / 0.32) * (sy > -0.35 ? 1 : 0);
    const nightF = 1 - smoothstep(-0.16, 0.10, sy);
    this.nightFactor = nightF;

    this.skyUniforms.topColor.value.copy(C.nightTop).lerp(C.dayTop, dayF);
    this.skyUniforms.topColor.value.lerp(C.duskTop, duskF * 0.62);
    this.skyUniforms.bottomColor.value.copy(C.nightBot).lerp(C.dayBot, dayF);
    this.skyUniforms.bottomColor.value.lerp(C.duskBot, duskF * 0.78);
    this.skyUniforms.sunDir.value.copy(this.sunDir);
    this.skyUniforms.nightMix.value = nightF;

    const fogCol = C.fogNight.clone().lerp(C.fogDay, dayF).lerp(C.fogDusk, duskF * 0.72);
    this.scene.fog.color.copy(fogCol);
    this.scene.fog.near = 120 + dayF * 55;
    this.scene.fog.far = 330 + dayF * 210;
    this.scene.background.copy(fogCol);

    this.hemi.intensity = 0.18 + dayF * 0.8;
    this.hemi.color.set(0x9fc6e8).lerp(new THREE.Color(0x1c2540), nightF);
    this.ambient.intensity = 0.08 + dayF * 0.16;
    this.sun.intensity = 0.12 + dayF * 2.05;
    this.sun.color.set(0xffcb8a).lerp(new THREE.Color(0xfff2d8), smoothstep(0.0, 0.35, sy));
    if (duskF > 0.2) this.sun.color.lerp(new THREE.Color(0xff9757), duskF * 0.5);

    // lights follow the action, camera never leaves the shadow box
    const lightDir = sy > -0.03 ? this.sunDir : this.moonDir;
    this.lightDir.copy(lightDir);
    const px = playerPos ? playerPos.x : 0;
    const pz = playerPos ? playerPos.z : 0;
    const py = playerPos ? playerPos.y : 0;
    this.sun.position.set(px + lightDir.x * 120, py + Math.max(0.1, lightDir.y) * 120, pz + lightDir.z * 120);
    this.sunTarget.position.set(px, py, pz);
    this.sun.castShadow = this.shadowsEnabled && dayF > 0.02;

    if (camera) {
      this.sky.position.copy(camera.position);
      this.stars.position.copy(camera.position);
      this.moon.position.copy(camera.position).addScaledVector(this.moonDir, 720);
      this.clouds.position.x = ((this.time * 2.2) % 500) - 250;
    }
    this.starMat.opacity = Math.pow(nightF, 1.3) * 0.95;
    this.moonMat.opacity = 1;
    this.moon.visible = nightF > 0.08;

    // clouds tint with the sun
    this.cloudMat.color.set(0xffffff).lerp(new THREE.Color(0x222a3c), nightF * 0.85);
    this.cloudMat.opacity = 0.8 - nightF * 0.24;

    this.waterTex.offset.x = this.time * 0.0025;
    this.waterTex.offset.y = this.time * 0.0015;
    this.waterMat.color.set(0x2f7da5).lerp(new THREE.Color(0x07121e), nightF * 0.78);
    this.waterMat.opacity = 0.78 - nightF * 0.08;

    for (const mat of this._facadeMats) {
      if (mat) mat.emissiveIntensity = nightF * 1.35;
    }
    if (this._lampMat) {
      this._lampMat.color.set(0x5a6068).lerp(new THREE.Color(0xffe2a0), nightF);
    }
  }

  getClock() {
    const totalMinutes = Math.floor(this.dayTime * 24 * 60);
    const h = Math.floor(totalMinutes / 60) % 24;
    const m = totalMinutes % 60;
    return { h, m, text: `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}` };
  }

  getDayLabel() {
    const days = ['MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT', 'SUN'];
    return days[Math.floor(this.dayTime * 7) % 7];
  }
}

import * as THREE from 'three';
import { clamp, hashString } from '../rng.js';
import { createHeightSampler, STEP, SEA_LEVEL } from './height.js';
import { City } from './city.js';
import { TerrainChunks, makeTerrainMaterial } from './chunks.js';
import { Environment } from './sky.js';
import { makeNoiseTexture } from '../textures.js';

const MAP_SIZE = 1200;
const MAP_SPAN = 1200;

const BIOME_CSS = {
  ocean: [36, 84, 122],
  beach: [196, 178, 118],
  plains: [100, 148, 63],
  forest: [58, 111, 49],
  desert: [190, 166, 102],
  snow: [219, 228, 232],
  rock: [125, 125, 117],
  city: [139, 141, 136],
};

export class World {
  constructor(scene, seed, renderer) {
    this.scene = scene;
    this.seed = seed;
    this.renderer = renderer;

    this.height = createHeightSampler(seed);
    this.city = new City(seed, this.height);
    this.noiseTex = makeNoiseTexture();
    this.terrainMat = makeTerrainMaterial(this.noiseTex);

    const cityBuild = this.city.build(this.noiseTex);
    scene.add(cityBuild.group);

    this.chunks = new TerrainChunks(scene, seed, this.height, this.city, this.terrainMat);
    this.chunks.initial(this.city.spawn);

    this.env = new Environment(scene, seed, this.city, this.noiseTex, renderer);
    this.env.setCityMaterials(this.city.facadeMats, this.city.lampMat);

    // fountain water disc
    const plaza = this.city.lots.find(l => l.type === 'plaza');
    this.fountainMat = new THREE.MeshPhongMaterial({
      color: 0x3d92b8, transparent: true, opacity: 0.82, shininess: 110, specular: 0xd8f4ff,
    });
    if (plaza) {
      const disc = new THREE.Mesh(new THREE.CircleGeometry(3.35, 20), this.fountainMat);
      disc.rotation.x = -Math.PI / 2;
      disc.position.set(plaza.x, this.city.groundY + 0.95, plaza.z);
      disc.renderOrder = 1;
      scene.add(disc);
      this.fountain = disc;
    }

    this.buildColliderGrid();
    this.buildMap();
    this._roots = [cityBuild.group, this.chunks.group, this.env.sky, this.env.stars, this.env.moon, this.env.clouds, this.env.water, this.fountain].filter(Boolean);

    this._raycaster = new THREE.Raycaster();
    this._tmpV = new THREE.Vector3();
  }

  get groundY() { return this.city.groundY; }

  buildColliderGrid() {
    this.cell = 24;
    this.colliderGrid = new Map();
    for (const c of this.city.colliders) {
      const x0 = Math.floor(c.x0 / this.cell), x1 = Math.floor(c.x1 / this.cell);
      const z0 = Math.floor(c.z0 / this.cell), z1 = Math.floor(c.z1 / this.cell);
      for (let gz = z0; gz <= z1; gz++) {
        for (let gx = x0; gx <= x1; gx++) {
          const k = gx + ':' + gz;
          let arr = this.colliderGrid.get(k);
          if (!arr) { arr = []; this.colliderGrid.set(k, arr); }
          arr.push(c);
        }
      }
    }
  }

  queryColliders(x, z, r = 1) {
    const gx = Math.floor(x / this.cell), gz = Math.floor(z / this.cell);
    const span = Math.max(1, Math.ceil(r / this.cell));
    const out = [];
    const seen = new Set();
    for (let j = -span; j <= span; j++) {
      for (let i = -span; i <= span; i++) {
        const arr = this.colliderGrid.get((gx + i) + ':' + (gz + j));
        if (!arr) continue;
        for (const c of arr) {
          if (seen.has(c)) continue;
          seen.add(c);
          out.push(c);
        }
      }
    }
    return out;
  }

  /**
   * Push a circle out of any building it overlaps. Returns corrected x/z.
   */
  resolveCircle(x, z, r) {
    const cols = this.queryColliders(x, z, r + 2);
    let px = x, pz = z;
    for (let pass = 0; pass < 2; pass++) {
      let moved = false;
      for (const c of cols) {
        if (px + r > c.x0 && px - r < c.x1 && pz + r > c.z0 && pz - r < c.z1) {
          const left = px + r - c.x0;
          const right = c.x1 - (px - r);
          const top = pz + r - c.z0;
          const bottom = c.z1 - (pz - r);
          const m = Math.min(left, right, top, bottom);
          if (m === left) px -= left;
          else if (m === right) px += right;
          else if (m === top) pz -= top;
          else pz += bottom;
          moved = true;
        }
      }
      if (!moved) break;
    }
    return { x: px, z: pz };
  }

  isBlocked(x, z, pad = 0.3) {
    for (const c of this.queryColliders(x, z, pad + 1)) {
      if (x > c.x0 - pad && x < c.x1 + pad && z > c.z0 - pad && z < c.z1 + pad) return true;
    }
    return false;
  }

  groundAt(x, z) {
    return this.height.heightAt(x, z, this.city);
  }

  slopeAt(x, z) {
    return this.height.slopeAt(x, z, this.city);
  }

  isWater(x, z) {
    return this.groundAt(x, z) < SEA_LEVEL - 0.2;
  }

  /** Ray vs. buildings + stepped terrain. Used for bullets and third-person camera. */
  raycastStatic(origin, dir, maxDist = 80, includeGround = true) {
    let best = maxDist;
    for (const c of this.city.colliders) {
      const t = rayBox(origin, dir, c, best);
      if (t !== null) best = t;
    }
    if (includeGround) {
      const step = 1.25;
      for (let t = step; t < best; t += step) {
        const x = origin.x + dir.x * t;
        const y = origin.y + dir.y * t;
        const z = origin.z + dir.z * t;
        if (y < this.groundAt(x, z) + 0.15) { best = t; break; }
      }
    }
    return {
      dist: best,
      point: new THREE.Vector3(origin.x + dir.x * best, origin.y + dir.y * best, origin.z + dir.z * best),
    };
  }

  update(dt, camera, playerPos) {
    this.env.update(dt, camera, playerPos);
    this.chunks.update(playerPos);
  }

  // ---------------------------------------------------------------- map
  buildMap() {
    const canvas = document.createElement('canvas');
    canvas.width = MAP_SIZE;
    canvas.height = MAP_SIZE;
    const ctx = canvas.getContext('2d');
    const span = MAP_SPAN;
    const ox = this.city.cx - span / 2;
    const oz = this.city.cz - span / 2;
    const step = 5;
    const px = MAP_SIZE / span;

    ctx.fillStyle = '#17435f';
    ctx.fillRect(0, 0, MAP_SIZE, MAP_SIZE);

    for (let wz = 0; wz < span; wz += step) {
      for (let wx = 0; wx < span; wx += step) {
        const x = ox + wx, z = oz + wz;
        const h = this.height.heightAt(x, z, this.city);
        const biome = this.height.biomeAt(x, z, this.city);
        let c = BIOME_CSS[biome] || BIOME_CSS.plains;
        let shade = 1;
        if (h < SEA_LEVEL - 0.2) {
          const depth = clamp((SEA_LEVEL - h) / 20, 0, 1);
          c = [28 + (1 - depth) * 18, 70 + (1 - depth) * 34, 100 + (1 - depth) * 32];
        } else {
          shade = 0.82 + clamp(h / 90, 0, 1) * 0.34;
          // cheap banded shading
          shade *= 0.94 + ((Math.sin(x * 0.11) + Math.sin(z * 0.13)) * 0.5 + 0.5) * 0.12;
        }
        ctx.fillStyle = `rgb(${(c[0] * shade) | 0},${(c[1] * shade) | 0},${(c[2] * shade) | 0})`;
        ctx.fillRect(wx * px, wz * px, step * px + 0.6, step * px + 0.6);
      }
    }

    // City overlay
    const s = px;
    const toX = (x) => (x - ox) * px;
    const toY = (z) => (z - oz) * px;
    const city = this.city;
    // base block area
    ctx.fillStyle = '#71736e';
    ctx.fillRect(toX(city.cx - city.half), toY(city.cz - city.half), city.half * 2 * px, city.half * 2 * px);

    // lots
    for (const lot of city.lots) {
      let fill = '#8c8a80';
      if (lot.type === 'park' || lot.type === 'plaza') fill = '#4c833b';
      else if (lot.type === 'parking') fill = '#42464b';
      else if (lot.type === 'construction') fill = '#8a744c';
      ctx.fillStyle = fill;
      ctx.fillRect(toX(lot.x - lot.w / 2), toY(lot.z - lot.d / 2), lot.w * px, lot.d * px);
    }
    // roads
    ctx.strokeStyle = '#34383d';
    ctx.lineWidth = city.roadWidth * px;
    for (const x of city.xLines) {
      ctx.beginPath();
      ctx.moveTo(toX(x), toY(city.cz - 140));
      ctx.lineTo(toX(x), toY(city.cz + 140));
      ctx.stroke();
    }
    for (const z of city.zLines) {
      ctx.beginPath();
      ctx.moveTo(toX(city.cx - 140), toY(z));
      ctx.lineTo(toX(city.cx + 140), toY(z));
      ctx.stroke();
    }
    // buildings (roofs)
    for (const b of city.buildings) {
      ctx.fillStyle = b.h > 28 ? '#2e333a' : '#4a4e52';
      ctx.fillRect(toX(b.x - b.baseW / 2), toY(b.z - b.baseD / 2), b.baseW * px, b.baseD * px);
      if (b.h > 22) {
        ctx.fillStyle = 'rgba(255,255,255,0.1)';
        ctx.fillRect(toX(b.x - b.baseW / 2) + 1, toY(b.z - b.baseD / 2) + 1, Math.max(1, b.baseW * px - 2), 1);
      }
    }
    // job markers will be drawn dynamically.

    this.mapCanvas = canvas;
    this.mapOrigin = { x: ox, z: oz };
    this.mapScale = px;
  }

  worldToMap(x, z) {
    return {
      x: (x - this.mapOrigin.x) * this.mapScale,
      y: (z - this.mapOrigin.z) * this.mapScale,
    };
  }

  biomeLabel(x, z) {
    const b = this.height.biomeAt(x, z, this.city);
    const labels = {
      ocean: 'OPEN WATER', beach: 'SANDY COAST', plains: 'GRAND PLAINS', forest: 'PINE RIDGE',
      desert: 'RED MESA', snow: 'FROSTPEAK', rock: 'IRON HILLS', city: 'SAN VOXEL',
    };
    return labels[b] || 'THE WILDS';
  }

  locationName(x, z) {
    const d = Math.max(Math.abs(x - this.city.cx), Math.abs(z - this.city.cz));
    if (d < 205) return this.city.districtAt(x, z);
    return this.biomeLabel(x, z) + ' COUNTY';
  }

  randomRoadSpawn(rng) {
    return this.city.randomRoadSpawn(rng);
  }

  dispose() {
    for (const root of this._roots) {
      if (!root) continue;
      this.scene.remove(root);
    }
    this.scene.remove(this.env.sun);
    this.scene.remove(this.env.hemi);
    this.scene.remove(this.env.ambient);
    this.scene.remove(this.env.sunTarget);
    this.env.sun.dispose?.();
    this.env.hemi.dispose?.();
    this.chunks.chunks.forEach(c => c.mesh.geometry.dispose());
    this.city.group.traverse(o => {
      if (o.isMesh) {
        o.geometry.dispose();
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        for (const m of mats) {
          if (!m) continue;
          for (const k of ['map', 'emissiveMap']) if (m[k]) m[k].dispose();
          m.dispose();
        }
      }
    });
    if (this.fountainMat) this.fountainMat.dispose();
    this.noiseTex.dispose();
    this.env.waterTex.dispose();
  }
}

function rayBox(origin, dir, c, maxDist) {
  let tmin = 0, tmax = maxDist;
  const axes = [
    [origin.x, dir.x, c.x0, c.x1],
    [origin.y, dir.y, c.y0, c.y1],
    [origin.z, dir.z, c.z0, c.z1],
  ];
  for (const [o, d, min, max] of axes) {
    if (Math.abs(d) < 1e-7) {
      if (o < min || o > max) return null;
    } else {
      let t1 = (min - o) / d;
      let t2 = (max - o) / d;
      if (t1 > t2) { const t = t1; t1 = t2; t2 = t; }
      tmin = Math.max(tmin, t1);
      tmax = Math.min(tmax, t2);
      if (tmin > tmax) return null;
    }
  }
  return tmin >= 0 ? tmin : (tmax >= 0 ? tmax : null);
}

const KEY_FORWARD = new Set(['KeyW', 'ArrowUp']);
const KEY_BACK = new Set(['KeyS', 'ArrowDown']);
const KEY_LEFT = new Set(['KeyA', 'ArrowLeft']);
const KEY_RIGHT = new Set(['KeyD', 'ArrowRight']);

export class Input {
  constructor(canvas, game) {
    this.canvas = canvas;
    this.game = game;
    this.keys = new Set();
    this.lookX = 0;
    this.lookY = 0;
    this.moveX = 0; // analog: right
    this.moveY = 0; // analog: forward
    this.shoot = false;
    this.aim = false;
    this.sprint = false;
    this.jumpHeld = false;
    this.pressed = {
      jump: false, interact: false, reload: false, map: false,
      pause: false, horn: false, toggleSound: false, camera: false,
    };
    this.pointerLocked = false;
    this.dragging = false;
    this.lastPointer = { x: 0, y: 0 };
    this.isMobile = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.touchLookId = null;
    this.joystickId = null;
    this.joystickCenter = { x: 0, y: 0 };
    this.bind();
  }

  bind() {
    window.addEventListener('keydown', (e) => {
      if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA')) return;
      if (e.code === 'Space' || e.code === 'Tab') e.preventDefault();
      if (this.keys.has(e.code)) return;
      this.keys.add(e.code);
      if (e.code === 'KeyE') this.pressed.interact = true;
      if (e.code === 'KeyR') this.pressed.reload = true;
      if (e.code === 'KeyM') this.pressed.map = true;
      if (e.code === 'Escape') this.pressed.pause = true;
      if (e.code === 'KeyH') this.pressed.horn = true;
      if (e.code === 'KeyM') this.pressed.map = true;
      if (e.code === 'Space') this.pressed.jump = true;
      if (e.code === 'KeyC') this.pressed.camera = true;
      if (e.code === 'KeyN') this.pressed.toggleSound = true;
    });
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.shoot = false;
      this.aim = false;
    });

    this.canvas.addEventListener('mousedown', (e) => {
      if (this.game.state !== 'playing') return;
      if (!this.isMobile && !this.pointerLocked) {
        this.canvas.requestPointerLock?.();
      }
      if (e.button === 0) this.shoot = true;
      if (e.button === 2) this.aim = true;
      this.dragging = true;
      this.lastPointer.x = e.clientX;
      this.lastPointer.y = e.clientY;
    });
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) this.shoot = false;
      if (e.button === 2) this.aim = false;
      this.dragging = false;
    });
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
    window.addEventListener('mousemove', (e) => {
      if (this.game.state !== 'playing') return;
      if (this.pointerLocked) {
        this.lookX += e.movementX;
        this.lookY += e.movementY;
      } else if (this.dragging) {
        this.lookX += e.clientX - this.lastPointer.x;
        this.lookY += e.clientY - this.lastPointer.y;
        this.lastPointer.x = e.clientX;
        this.lastPointer.y = e.clientY;
      }
    });
    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === this.canvas;
    });
    this.canvas.addEventListener('wheel', (e) => {
      if (this.game.state !== 'playing') return;
      this.game.cameraZoomDelta = Math.sign(e.deltaY) * 0.55;
      e.preventDefault();
    }, { passive: false });

    // ---------------- touch controls ----------------
    const joy = document.getElementById('joystick');
    const zone = document.getElementById('joystick-zone');
    if (joy && zone) {
      const start = (e) => {
        e.preventDefault();
        const t = e.changedTouches[0];
        const r = joy.getBoundingClientRect();
        this.joystickCenter.x = r.left + r.width / 2;
        this.joystickCenter.y = r.top + r.height / 2;
        this.joystickId = t.identifier;
        this.updateJoystick(t.clientX, t.clientY, r.width / 2);
      };
      const move = (e) => {
        for (const t of e.changedTouches) {
          if (t.identifier === this.joystickId) {
            const r = joy.getBoundingClientRect();
            this.updateJoystick(t.clientX, t.clientY, r.width / 2);
            e.preventDefault();
          }
        }
      };
      const end = (e) => {
        for (const t of e.changedTouches) {
          if (t.identifier === this.joystickId) {
            this.joystickId = null;
            this.moveX = 0;
            this.moveY = 0;
            const knob = document.getElementById('joystick-knob');
            if (knob) knob.style.transform = 'translate(-50%,-50%)';
          }
        }
      };
      zone.addEventListener('touchstart', start, { passive: false });
      zone.addEventListener('touchmove', move, { passive: false });
      zone.addEventListener('touchend', end, { passive: false });
      zone.addEventListener('touchcancel', end, { passive: false });
    }

    const lookZone = document.getElementById('app');
    lookZone.addEventListener('touchstart', (e) => {
      if (this.game.state !== 'playing') return;
      for (const t of e.changedTouches) {
        if (t.clientX < window.innerWidth * 0.38) continue;
        if (this.touchLookId === null) {
          this.touchLookId = t.identifier;
          this.lastPointer.x = t.clientX;
          this.lastPointer.y = t.clientY;
        }
      }
    }, { passive: true });
    lookZone.addEventListener('touchmove', (e) => {
      if (this.game.state !== 'playing') return;
      for (const t of e.changedTouches) {
        if (t.identifier !== this.touchLookId) continue;
        this.lookX += (t.clientX - this.lastPointer.x) * 1.0;
        this.lookY += (t.clientY - this.lastPointer.y) * 1.0;
        this.lastPointer.x = t.clientX;
        this.lastPointer.y = t.clientY;
      }
    }, { passive: true });
    lookZone.addEventListener('touchend', (e) => {
      for (const t of e.changedTouches) {
        if (t.identifier === this.touchLookId) this.touchLookId = null;
      }
    }, { passive: true });

    const bindBtn = (id, down) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('touchstart', (e) => { e.preventDefault(); e.stopPropagation(); down(true); }, { passive: false });
      el.addEventListener('touchend', (e) => { e.preventDefault(); e.stopPropagation(); down(false); }, { passive: false });
      el.addEventListener('touchcancel', (e) => { e.preventDefault(); down(false); }, { passive: false });
      el.addEventListener('mousedown', (e) => { e.preventDefault(); e.stopPropagation(); down(true); });
      el.addEventListener('mouseup', (e) => { e.preventDefault(); e.stopPropagation(); down(false); });
    };
    bindBtn('btn-fire', (v) => { this.shoot = v; });
    bindBtn('btn-jump', (v) => {
      if (v) this.pressed.jump = true;
      this.jumpHeld = v;
    });
    bindBtn('btn-enter', (v) => { if (v) this.pressed.interact = true; });
    bindBtn('btn-reload', (v) => { if (v) this.pressed.reload = true; });
    bindBtn('btn-menu', (v) => { if (v) this.pressed.pause = true; });
  }

  updateJoystick(x, y, radius) {
    let dx = x - this.joystickCenter.x;
    let dy = y - this.joystickCenter.y;
    const len = Math.hypot(dx, dy);
    const max = radius * 0.78;
    if (len > max) { dx = dx / len * max; dy = dy / len * max; }
    this.moveX = dx / max;
    this.moveY = -dy / max;
    const knob = document.getElementById('joystick-knob');
    if (knob) knob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
  }

  /** Forward axis from keyboard / joystick. */
  get forward() {
    let v = 0;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) v += 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) v -= 1;
    if (Math.abs(this.moveY) > 0.02) v = this.moveY;
    return Math.max(-1, Math.min(1, v));
  }

  get strafe() {
    let v = 0;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) v += 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) v -= 1;
    if (Math.abs(this.moveX) > 0.02) v = this.moveX;
    return Math.max(-1, Math.min(1, v));
  }

  get sprinting() {
    return this.sprint || this.keys.has('ShiftLeft') || this.keys.has('ShiftRight');
  }

  get jump() {
    return this.jumpHeld || this.keys.has('Space');
  }

  consume() {
    const p = { ...this.pressed };
    for (const k in this.pressed) this.pressed[k] = false;
    const look = { x: this.lookX, y: this.lookY };
    this.lookX = 0;
    this.lookY = 0;
    return { pressed: p, look };
  }

  clearFrame() {
    this.lookX = 0;
    this.lookY = 0;
  }
}

export { KEY_FORWARD, KEY_BACK, KEY_LEFT, KEY_RIGHT };

/** Tiny WebAudio synth: no external assets, everything is generated. */
export class Audio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.engine = null;
    this.siren = null;
    this.sirenOn = false;
    this._lastHit = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.55;
    this.master.connect(this.ctx.destination);
    this.buildEngine();
    this.buildSiren();
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.05);
  }

  buildEngine() {
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    const osc2 = ctx.createOscillator();
    const filter = ctx.createBiquadFilter();
    const gain = ctx.createGain();
    osc.type = 'sawtooth';
    osc2.type = 'square';
    osc.frequency.value = 55;
    osc2.frequency.value = 27;
    filter.type = 'lowpass';
    filter.frequency.value = 300;
    filter.Q.value = 4;
    gain.gain.value = 0;
    osc.connect(filter);
    osc2.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    osc.start();
    osc2.start();
    this.engine = { osc, osc2, filter, gain };
  }

  buildSiren() {
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.value = 700;
    gain.gain.value = 0;
    osc.connect(gain);
    gain.connect(this.master);
    osc.start();
    this.siren = { osc, gain };
  }

  updateEngine(speed, throttle, active) {
    if (!this.engine) return;
    const t = this.ctx.currentTime;
    const s = Math.abs(speed);
    const target = active ? 0.035 + Math.min(0.075, s * 0.0021) : 0;
    this.engine.gain.gain.setTargetAtTime(target, t, 0.09);
    this.engine.osc.frequency.setTargetAtTime(46 + s * 3.6 + Math.abs(throttle) * 12, t, 0.08);
    this.engine.osc2.frequency.setTargetAtTime(23 + s * 1.8, t, 0.1);
    this.engine.filter.frequency.setTargetAtTime(220 + s * 22 + Math.abs(throttle) * 180, t, 0.1);
  }

  updateSiren(active, time) {
    if (!this.siren) return;
    if (active !== this.sirenOn) {
      this.sirenOn = active;
      this.siren.gain.gain.setTargetAtTime(active ? 0.025 : 0, this.ctx.currentTime, 0.2);
    }
    if (active) {
      const f = 620 + (Math.sin(time * 3.2) > 0 ? 280 : 0);
      this.siren.osc.frequency.setTargetAtTime(f, this.ctx.currentTime, 0.08);
    }
  }

  noiseBurst(duration = 0.16, vol = 0.35, cutoff = 1800, type = 'lowpass') {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const len = Math.floor(ctx.sampleRate * duration);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) {
      const fade = 1 - i / len;
      d[i] = (Math.random() * 2 - 1) * fade * fade;
    }
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = cutoff;
    const g = ctx.createGain();
    g.gain.value = vol;
    g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start();
  }

  gunshot() {
    if (!this.ctx) return;
    this.noiseBurst(0.14, 0.45, 2200);
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = 'square';
    o.frequency.setValueAtTime(140, ctx.currentTime);
    o.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.09);
    g.gain.setValueAtTime(0.22, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
    o.connect(g);
    g.connect(this.master);
    o.start();
    o.stop(ctx.currentTime + 0.12);
  }

  copShot() {
    if (!this.ctx) return;
    this.noiseBurst(0.1, 0.18, 1400);
  }

  hit() {
    if (!this.ctx) return;
    if (this.ctx.currentTime - this._lastHit < 0.06) return;
    this._lastHit = this.ctx.currentTime;
    this.noiseBurst(0.08, 0.24, 700);
  }

  crash(strength = 1) {
    if (!this.ctx) return;
    this.noiseBurst(0.22, Math.min(0.5, 0.18 * strength), 500);
  }

  explosion() {
    if (!this.ctx) return;
    this.noiseBurst(0.85, 0.65, 320);
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(75, ctx.currentTime);
    o.frequency.exponentialRampToValueAtTime(18, ctx.currentTime + 0.7);
    g.gain.setValueAtTime(0.4, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.8);
    o.connect(g);
    g.connect(this.master);
    o.start();
    o.stop(ctx.currentTime + 0.9);
  }

  beep(freq = 660, dur = 0.08, vol = 0.12, type = 'square') {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = type;
    o.frequency.value = freq;
    g.gain.setValueAtTime(vol, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + dur);
    o.connect(g);
    g.connect(this.master);
    o.start();
    o.stop(ctx.currentTime + dur + 0.02);
  }

  pickup() {
    this.beep(520, 0.08, 0.13);
    setTimeout(() => this.beep(780, 0.12, 0.12), 70);
    setTimeout(() => this.beep(1040, 0.14, 0.1), 145);
  }

  missionDone() {
    this.beep(520, 0.12, 0.13, 'sawtooth');
    setTimeout(() => this.beep(660, 0.12, 0.13, 'sawtooth'), 120);
    setTimeout(() => this.beep(880, 0.3, 0.14, 'sawtooth'), 240);
  }

  fail() {
    this.beep(180, 0.22, 0.16, 'sawtooth');
    setTimeout(() => this.beep(120, 0.35, 0.14, 'sawtooth'), 180);
  }

  reload() {
    this.beep(320, 0.05, 0.08, 'square');
    setTimeout(() => this.beep(220, 0.06, 0.08, 'square'), 140);
  }

  horn() {
    if (!this.ctx) return;
    const ctx = this.ctx;
    for (const f of [392, 495]) {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = 'square';
      o.frequency.value = f;
      g.gain.setValueAtTime(0.09, ctx.currentTime);
      g.gain.setValueAtTime(0.09, ctx.currentTime + 0.35);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.45);
      o.connect(g);
      g.connect(this.master);
      o.start();
      o.stop(ctx.currentTime + 0.46);
    }
  }
}

export const audio = new Audio();

