import * as THREE from 'three';
import { GeoBuilder, col } from './world/geo.js';
import { stream, clamp } from './rng.js';

const TYPES = {
  sedan: { len: 4.2, width: 1.9, bodyH: 0.55, cabLen: 1.75, cabZ: -0.25, cabH: 0.52, roofH: 0.12 },
  coupe: { len: 3.85, width: 1.86, bodyH: 0.5, cabLen: 1.5, cabZ: -0.3, cabH: 0.45, roofH: 0.1 },
  van: { len: 4.75, width: 2.0, bodyH: 0.72, cabLen: 2.7, cabZ: -0.25, cabH: 0.95, roofH: 0.12 },
};

const geomCache = new Map();

function buildCar(type, police = false) {
  const p = TYPES[type] || TYPES.sedan;
  const body = new GeoBuilder(false);
  const detail = new GeoBuilder(false);
  const hw = p.width / 2;
  const hl = p.len / 2;
  const bodyY = 0.36;
  const white = col(0xffffff);
  const off = col(0xdedede);
  const glass = col(0x1b2a35);
  const glassLight = col(0x35505f);
  const black = col(0x171a1e);
  const trim = col(0x2b2f34);
  const chrome = col(0xaeb6ba);
  const head = col(0xffe9a6);
  const tail = col(0xd83a2f);

  // lower body
  body.box(0, bodyY, 0, p.width, p.bodyH, p.len, white, 2);
  // hood / trunk caps
  body.box(0, bodyY + p.bodyH, hl - 0.7, p.width * 0.94, 0.12, 1.25, off, 2);
  body.box(0, bodyY + p.bodyH, -hl + 0.65, p.width * 0.94, 0.12, 1.0, off, 2);
  // cabin frame (white pillars) + roof
  const cabY = bodyY + p.bodyH;
  body.box(0, cabY + p.cabH, p.cabZ, p.width * 0.86, p.roofH, p.cabLen * 0.92, white, 2);
  // roof rack on van
  if (type === 'van') {
    body.box(0, cabY + p.cabH + p.roofH, p.cabZ, p.width * 0.7, 0.08, p.cabLen * 0.6, trim, 2);
  }
  // details: glass band
  detail.box(0, cabY + 0.06, p.cabZ, p.width * 0.84, p.cabH - 0.07, p.cabLen, glass, 2);
  // windshield / rear slant hint
  detail.box(0, cabY + 0.07, p.cabZ + p.cabLen / 2 - 0.06, p.width * 0.72, p.cabH - 0.1, 0.06, glassLight, 2);
  // bumpers
  detail.box(0, bodyY + 0.08, hl + 0.06, p.width * 0.98, 0.24, 0.16, trim, 2);
  detail.box(0, bodyY + 0.08, -hl - 0.06, p.width * 0.98, 0.24, 0.16, trim, 2);
  // grille
  detail.box(0, bodyY + 0.28, hl + 0.08, p.width * 0.45, 0.18, 0.06, black, 1);
  // lights
  for (const sx of [-1, 1]) {
    detail.box(sx * p.width * 0.34, bodyY + 0.3, hl + 0.09, 0.34, 0.17, 0.05, head, 1);
    detail.box(sx * p.width * 0.34, bodyY + 0.3, -hl - 0.09, 0.34, 0.17, 0.05, tail, 1);
  }
  // side mirrors
  detail.box(hw + 0.08, cabY + 0.2, p.cabZ + p.cabLen / 2 - 0.1, 0.18, 0.16, 0.24, trim, 1);
  detail.box(-hw - 0.08, cabY + 0.2, p.cabZ + p.cabLen / 2 - 0.1, 0.18, 0.16, 0.24, trim, 1);
  // wheels
  const wheelY = 0.33;
  const wx = hw - 0.03;
  for (const sx of [-1, 1]) {
    for (const sz of [1.3, -1.3]) {
      detail.box(sx * wx, wheelY, sz, 0.3, 0.66, 0.78, black, 1);
      detail.box(sx * (wx + 0.02), wheelY, sz, 0.08, 0.34, 0.36, chrome, 1);
    }
  }
  // police livery
  if (police) {
    detail.box(hw + 0.01, bodyY + 0.4, 0, 0.02, 0.3, 1.5, black, 1);
    detail.box(-hw - 0.01, bodyY + 0.4, 0, 0.02, 0.3, 1.5, black, 1);
    detail.box(0, bodyY + p.bodyH + 0.03, p.cabZ, p.width * 0.5, 0.06, 0.8, black, 1);
  }
  return { body: body.build(), detail: detail.build(), bodyMat: null };
}

function getGeom(type, police) {
  const k = type + (police ? ':p' : '');
  if (!geomCache.has(k)) geomCache.set(k, buildCar(type, police));
  return geomCache.get(k);
}

const detailMaterial = new THREE.MeshLambertMaterial({ vertexColors: true });
const wreckMaterial = new THREE.MeshLambertMaterial({ color: 0x1c1d1e });

let carId = 0;

export class Vehicle {
  constructor(game, opts = {}) {
    this.game = game;
    this.id = carId++;
    this.type = opts.type || 'sedan';
    this.police = !!opts.police;
    this.color = opts.color ?? 0xa52f2f;
    this.pos = new THREE.Vector3(opts.x || 0, 0, opts.z || 0);
    this.yaw = opts.yaw || 0;
    this.speed = 0;
    this.steer = 0;
    this.health = opts.health ?? 100;
    this.maxHealth = 100;
    this.driver = opts.driver ?? null; // 'player' | 'ai' | null
    this.destroyed = false;
    this.ai = null;
    this.pitch = 0;
    this.roll = 0;
    this.stuckTime = 0;
    this.smokeTimer = 0;
    this.explosionTimer = -1;
    this.aiType = opts.aiType || 'traffic';
    this.colorName = opts.colorName;

    const geom = getGeom(this.type, this.police);
    this.bodyMat = new THREE.MeshLambertMaterial({ vertexColors: true, color: this.color });
    this.group = new THREE.Group();
    this.bodyMesh = new THREE.Mesh(geom.body, this.bodyMat);
    this.bodyMesh.castShadow = true;
    this.bodyMesh.receiveShadow = true;
    this.group.add(this.bodyMesh);
    this.detailMesh = new THREE.Mesh(geom.detail, detailMaterial);
    this.detailMesh.castShadow = true;
    this.group.add(this.detailMesh);

    if (this.police) {
      this.lightRed = new THREE.MeshBasicMaterial({ color: 0x550b0b });
      this.lightBlue = new THREE.MeshBasicMaterial({ color: 0x0a1e55 });
      const lbBase = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.12, 0.3), new THREE.MeshLambertMaterial({ color: 0x15181c }));
      lbBase.position.set(0, 1.62, -0.2);
      this.group.add(lbBase);
      const red = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.16, 0.26), this.lightRed);
      red.position.set(-0.25, 1.73, -0.2);
      const blue = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.16, 0.26), this.lightBlue);
      blue.position.set(0.25, 1.73, -0.2);
      this.group.add(red, blue);
      this.lightbar = { red, blue, base: lbBase };
    }

    this.syncMesh(0);
    game.scene.add(this.group);

    if (this.driver === 'ai') {
      if (this.police) this.initPoliceAI();
      else this.initTrafficAI(game);
    }
    this.y = game.world.groundAt(this.pos.x, this.pos.z);
    this.syncMesh(0);
  }

  get forwardX() { return Math.sin(this.yaw); }
  get forwardZ() { return Math.cos(this.yaw); }

  syncMesh() {
    const w = this.game.world;
    const gy = w.groundAt(this.pos.x, this.pos.z);
    this.pos.y += (gy - this.pos.y) * 0.35;
    if (Math.abs(this.pos.y - gy) > 2) this.pos.y = gy;
    const fx = this.pos.x + Math.sin(this.yaw) * 1.4;
    const fz = this.pos.z + Math.cos(this.yaw) * 1.4;
    const bx = this.pos.x - Math.sin(this.yaw) * 1.4;
    const bz = this.pos.z - Math.cos(this.yaw) * 1.4;
    const hf = w.groundAt(fx, fz);
    const hb = w.groundAt(bx, bz);
    this.pitch = -Math.atan2(hf - hb, 2.8);
    const rx = this.pos.x + Math.cos(this.yaw) * 0.9;
    const rz = this.pos.z - Math.sin(this.yaw) * 0.9;
    const lx = this.pos.x - Math.cos(this.yaw) * 0.9;
    const lz = this.pos.z + Math.sin(this.yaw) * 0.9;
    const hr = w.groundAt(rx, rz);
    const hl2 = w.groundAt(lx, lz);
    const targetRoll = Math.atan2(hr - hl2, 1.8);
    this.roll += (targetRoll - this.roll) * 0.2;
    this.group.position.set(this.pos.x, this.pos.y + 0.02, this.pos.z);
    this.group.rotation.set(this.pitch, this.yaw, this.roll, 'YXZ');
  }

  initTrafficAI(game) {
    const city = game.world.city;
    const rng = game.trafficRng;
    const ix = nearestIndex(city.xLines, this.pos.x);
    const iz = nearestIndex(city.zLines, this.pos.z);
    let dirX = 0, dirZ = 0;
    const a = Math.abs(Math.sin(this.yaw));
    if (a > 0.7) dirX = Math.sin(this.yaw) > 0 ? 1 : -1;
    else dirZ = Math.cos(this.yaw) > 0 ? 1 : -1;
    this.ai = {
      type: 'traffic', ix, iz, dirX, dirZ,
      target: null, cruise: 8.5 + (rng ? rng() : Math.random()) * 4.5,
      lane: 2.1, reverseTimer: 0, blocked: 0,
    };
    this.pickTrafficTarget(game);
  }

  pickTrafficTarget(game) {
    const city = game.world.city;
    const ai = this.ai;
    let nx = ai.ix, nz = ai.iz;
    if (ai.dirX !== 0) nx = clamp(nx + ai.dirX, 0, city.xLines.length - 1);
    if (ai.dirZ !== 0) nz = clamp(nz + ai.dirZ, 0, city.zLines.length - 1);
    ai.targetIx = nx;
    ai.targetIz = nz;
    const fx = ai.dirX, fz = ai.dirZ;
    const rx = -fz, rz = fx; // right-hand lane
    ai.target = {
      x: city.xLines[nx] + rx * ai.lane,
      z: city.zLines[nz] + rz * ai.lane,
    };
  }

  advanceTrafficTarget(game) {
    const city = game.world.city;
    const ai = this.ai;
    ai.ix = ai.targetIx;
    ai.iz = ai.targetIz;
    const options = [];
    if (ai.dirX !== 0) {
      if (ai.ix + ai.dirX >= 0 && ai.ix + ai.dirX < city.xLines.length) options.push({ x: ai.dirX, z: 0, w: 0.55 });
      if (ai.iz + 1 < city.zLines.length) options.push({ x: 0, z: 1, w: 0.225 });
      if (ai.iz - 1 >= 0) options.push({ x: 0, z: -1, w: 0.225 });
    } else {
      if (ai.iz + ai.dirZ >= 0 && ai.iz + ai.dirZ < city.zLines.length) options.push({ x: 0, z: ai.dirZ, w: 0.55 });
      if (ai.ix + 1 < city.xLines.length) options.push({ x: 1, z: 0, w: 0.225 });
      if (ai.ix - 1 >= 0) options.push({ x: -1, z: 0, w: 0.225 });
    }
    if (!options.length) {
      ai.dirX *= -1; ai.dirZ *= -1;
    } else {
      let r = Math.random();
      let pick = options[0];
      for (const o of options) { if (r < o.w) { pick = o; break; } r -= o.w; }
      ai.dirX = pick.x; ai.dirZ = pick.z;
    }
    this.pickTrafficTarget(game);
  }

  initPoliceAI() {
    this.ai = { type: 'police', stuck: 0, reverse: 0 };
  }

  update(dt, game) {
    if (this.destroyed) return;
    const player = game.player;
    let throttle = 0, steerInput = 0, handbrake = false;

    if (this.driver === 'player') {
      const inp = game.input;
      throttle = inp.forward;
      steerInput = -inp.strafe * 0.9;
      handbrake = inp.jump;
      // aim the car camera heading if no throttle? no
    } else if (this.driver === 'ai') {
      if (this.ai?.type === 'traffic') {
        const ai = this.ai;
        if (!ai.target) this.pickTrafficTarget(game);
        const dx = ai.target.x - this.pos.x;
        const dz = ai.target.z - this.pos.z;
        const dist = Math.hypot(dx, dz);
        if (dist < 3.2) {
          if (ai.reverseTimer > 0) { ai.reverseTimer -= dt; }
          else this.advanceTrafficTarget(game);
        }
        const desired = Math.atan2(dx, dz);
        let diff = wrapAngle(desired - this.yaw);
        steerInput = clamp(diff * 2.2, -1, 1);
        throttle = 0.46;
        // slow for the player / other cars ahead
        let blocked = false;
        const fx = Math.sin(this.yaw), fz = Math.cos(this.yaw);
        const checkAhead = (x, z, rad) => {
          const ox = x - this.pos.x, oz = z - this.pos.z;
          if (ox * ox + oz * oz > 90) return false;
          const dot = (ox * fx + oz * fz) / Math.max(0.001, Math.hypot(ox, oz));
          return dot > 0.65;
        };
        if (player && player.mesh.visible && checkAhead(player.pos.x, player.pos.z)) blocked = true;
        for (const v of game.vehicles.list) {
          if (v === this || v.destroyed) continue;
          if (checkAhead(v.pos.x, v.pos.z)) { blocked = true; break; }
        }
        if (blocked) throttle = -0.35;
        if (Math.abs(this.speed) < 1.2) {
          ai.blocked += dt;
          if (ai.blocked > 2.5) { ai.reverseTimer = 1.2; ai.blocked = 0; ai.dirX *= -1; ai.dirZ *= -1; this.pickTrafficTarget(game); }
        } else ai.blocked = 0;
        if (ai.reverseTimer > 0) { throttle = -1; steerInput *= -0.5; }
      } else {
        // police pursuit
        const ai = this.ai;
        const target = player.pos;
        const dx = target.x - this.pos.x;
        const dz = target.z - this.pos.z;
        const dist = Math.hypot(dx, dz);
        const desired = Math.atan2(dx, dz);
        const diff = wrapAngle(desired - this.yaw);
        steerInput = clamp(diff * 2.4, -1, 1);
        if (dist > 7) throttle = 1;
        else throttle = 0.1;
        if (ai.reverse > 0) {
          ai.reverse -= dt;
          throttle = -1;
          steerInput *= -1;
        }
        if (Math.abs(this.speed) < 1.4) ai.stuck += dt; else ai.stuck = 0;
        if (ai.stuck > 1.6) { ai.reverse = 1.1; ai.stuck = 0; }
        if (dist < 22 && player.mode === 'vehicle' && Math.random() < dt * 0.6) {
          game.spawnCopFromCar(this);
        }
      }
    }

    this.drive(dt, throttle, steerInput, handbrake, game);
    this.syncMesh(dt);

    if (this.police) {
      const t = game.time;
      const on = this.driver === 'ai' && game.player.wanted > 0;
      const flash = on ? (Math.sin(t * 12 + this.id) > 0) : false;
      this.lightRed.color.setHex(flash ? 0xff2222 : 0x550b0b);
      this.lightBlue.color.setHex(!flash ? 0x2277ff : 0x0a1e55);
    }

    // damage smoke / fire
    if (this.health < 38) {
      this.smokeTimer -= dt;
      if (this.smokeTimer <= 0) {
        this.smokeTimer = this.health < 15 ? 0.12 : 0.28;
        game.particles.smoke(new THREE.Vector3(this.pos.x, this.pos.y + 1.0, this.pos.z), this.health < 15 ? 0x3b3b3b : 0x8b8b8b, this.health < 15 ? 2 : 1, this.health < 15 ? 1.2 : 0.9);
      }
    }
  }

  drive(dt, throttleInput, steerInput, handbrake, game) {
    const playerDriver = this.driver === 'player';
    const throttle = clamp(throttleInput, -1, 1);
    const accel = this.type === 'van' ? 16 : this.police ? 22 : 20;
    const maxFwd = this.type === 'van' ? 29 : this.police ? 35 : 33;

    if (throttle > 0.03) {
      this.speed += accel * throttle * dt;
    } else if (throttle < -0.03) {
      if (this.speed > 0.4) this.speed += 32 * throttle * dt;
      else this.speed += accel * 0.55 * throttle * dt;
    } else {
      this.speed -= this.speed * 0.7 * dt;
    }
    if (handbrake) {
      this.speed *= Math.max(0, 1 - 3.2 * dt);
      if (playerDriver && Math.abs(this.speed) > 12) {
        game.particles.smoke(new THREE.Vector3(this.pos.x, this.pos.y + 0.3, this.pos.z), 0xbfbfbf, 1, 1.2);
      }
    }
    // drag + rolling resistance
    this.speed *= Math.max(0, 1 - 0.22 * dt);
    this.speed = clamp(this.speed, -12, maxFwd);

    // bicycle-ish steering, reduced at speed
    const steerTarget = clamp(steerInput, -1, 1);
    this.steer += (steerTarget - this.steer) * Math.min(1, dt * 9);
    const maxSteer = 0.58 / (1 + Math.abs(this.speed) * 0.085);
    const wheelbase = 2.7;
    if (Math.abs(this.speed) > 0.15) {
      const yawRate = (this.speed / wheelbase) * Math.tan(this.steer * maxSteer);
      this.yaw += yawRate * dt * (this.speed < 0 ? -1 : 1);
    }

    const fx = Math.sin(this.yaw), fz = Math.cos(this.yaw);
    let nx = this.pos.x + fx * this.speed * dt;
    let nz = this.pos.z + fz * this.speed * dt;

    // oriented collision with buildings - three sample circles along hull
    let hit = false;
    const world = game.world;
    for (const off of [-1.35, 0, 1.35]) {
      const sx = nx + fx * off, sz = nz + fz * off;
      const fixed = world.resolveCircle(sx, sz, 0.92);
      if (Math.abs(fixed.x - sx) > 0.001 || Math.abs(fixed.z - sz) > 0.001) {
        nx += fixed.x - sx;
        nz += fixed.z - sz;
        hit = true;
      }
    }
    const gy = world.groundAt(nx, nz);
    if (gy < -0.55) {
      // deep water: stall
      this.speed *= 0.82;
      if (playerDriver) game.notify('TOO DEEP', 'Your car will not swim. Find a road.', 'bad', 1600, true);
    }
    if (hit) {
      const impact = Math.abs(this.speed);
      if (impact > 4) {
        game.particles.sparks(new THREE.Vector3(nx + fx * 1.5, this.pos.y + 0.8, nz + fz * 1.5));
        game.audio.crash(impact / 12);
        this.health -= impact * 0.5;
        if (playerDriver) game.player.takeDamage(impact * 0.28, game, true);
      }
      this.speed *= -0.22;
    }
    this.pos.x = nx;
    this.pos.z = nz;

    // keep the car from clipping into the city's low walls on handbrake
    if (Math.abs(this.speed) < 0.05) this.speed = 0;
    if (this.health <= 0) this.explode(game);
  }

  explode(game) {
    if (this.destroyed) return;
    this.destroyed = true;
    const p = new THREE.Vector3(this.pos.x, this.pos.y + 0.8, this.pos.z);
    game.particles.explosion(p);
    game.audio.explosion();
    if (this.driver === 'player') {
      game.player.takeDamage(75, game);
      game.exitVehicle(true);
    } else if (this.game.player.pos.distanceTo(p) < 9) {
      game.player.takeDamage(40, game);
    }
    game.vehicles.remove(this);
    game.cameraShake = Math.max(game.cameraShake, 0.8);
    // charred wreck
    const wreck = new THREE.Mesh(getGeom(this.type, this.police).body, wreckMaterial);
    wreck.position.copy(this.group.position);
    wreck.rotation.copy(this.group.rotation);
    wreck.castShadow = true;
    game.scene.add(wreck);
    setTimeout(() => { game.scene.remove(wreck); }, 20000);
    void this.lightbar;
  }

  enter() {
    this.driver = 'player';
    this.ai = null;
    this.speed = 0;
    this.group.visible = true;
  }

  exit() {
    this.driver = null;
    this.ai = null;
  }

  damage(amount, game) {
    if (this.destroyed) return;
    this.health -= amount;
    if (this.health <= 0) this.explode(game);
  }
}

export class VehicleManager {
  constructor(game) {
    this.game = game;
    this.list = [];
    this.trafficRng = stream(game.seed, 'traffic');
    this.spawnTimer = 0;
    this.policeTimer = 0;
  }

  add(v) {
    this.list.push(v);
    return v;
  }

  remove(v) {
    const i = this.list.indexOf(v);
    if (i >= 0) this.list.splice(i, 1);
    this.game.scene.remove(v.group);
    v.bodyMat.dispose();
    if (v.lightRed) { v.lightRed.dispose(); v.lightBlue.dispose(); }
  }

  spawn(opts) {
    const v = new Vehicle(this.game, opts);
    this.add(v);
    return v;
  }

  populate() {
    const city = this.game.world.city;
    const rng = this.trafficRng;
    // parked cars in parking lots
    for (const spot of city.parkedSpots) {
      if (rng() < 0.35) continue;
      const type = rng() < 0.2 ? 'van' : rng() < 0.4 ? 'coupe' : 'sedan';
      this.spawn({
        x: spot.x, z: spot.z, yaw: spot.yaw + (rng() < 0.5 ? 0 : Math.PI),
        color: spot.color, type, driver: null,
      });
    }
    // street traffic
    for (let i = 0; i < 9; i++) {
      const s = city.randomRoadSpawn(rng);
      this.spawn({
        x: s.x, z: s.z, yaw: s.yaw,
        color: randomColor(rng), type: rng() < 0.18 ? 'van' : rng() < 0.32 ? 'coupe' : 'sedan',
        driver: 'ai', aiType: 'traffic',
      });
    }
    // a couple of hero parked cars near the plaza
    const spawn = city.spawn;
    for (let i = 0; i < 3; i++) {
      const x = spawn.x + 8 + i * 3.1;
      const z = spawn.z - 14 + i * 1.4;
      if (this.game.world.isBlocked(x, z, 1.2)) continue;
      this.spawn({
        x, z, yaw: Math.PI / 2, color: randomColor(rng),
        type: i === 0 ? 'coupe' : 'sedan', driver: null,
      });
    }
  }

  update(dt) {
    const game = this.game;
    for (const v of [...this.list]) v.update(dt, game);

    // keep ambient traffic populated
    this.spawnTimer -= dt;
    if (this.spawnTimer <= 0) {
      this.spawnTimer = 1.5;
      let traffic = 0;
      for (const v of this.list) {
        if (v.driver === 'ai' && !v.police && !v.destroyed) traffic++;
      }
      if (traffic < 10) {
        const p = game.player.pos;
        for (let tries = 0; tries < 8; tries++) {
          const s = game.world.city.randomRoadSpawn(this.trafficRng);
          const d = Math.hypot(s.x - p.x, s.z - p.z);
          if (d > 70 && d < 210) {
            this.spawn({
              x: s.x, z: s.z, yaw: s.yaw,
              color: randomColor(this.trafficRng),
              type: this.trafficRng() < 0.2 ? 'van' : this.trafficRng() < 0.35 ? 'coupe' : 'sedan',
              driver: 'ai', aiType: 'traffic',
            });
            break;
          }
        }
      }
      // despawn distant AI
      for (const v of [...this.list]) {
        if (v.driver === 'ai' && !v.police) {
          const d = Math.hypot(v.pos.x - p.x, v.pos.z - p.z);
          if (d > 320) this.remove(v);
        }
      }
    }
  }

  nearest(pos, maxDist = 4.5) {
    let best = null, bd = maxDist;
    for (const v of this.list) {
      if (v.destroyed) continue;
      const d = Math.hypot(v.pos.x - pos.x, v.pos.z - pos.z);
      if (d < bd) { bd = d; best = v; }
    }
    return best;
  }

  spawnPoliceCar(pos, rng = Math.random) {
    const world = this.game.world;
    for (let tries = 0; tries < 25; tries++) {
      const s = world.city.randomRoadSpawn(rng);
      const d = Math.hypot(s.x - pos.x, s.z - pos.z);
      if (d > 55 && d < 130) {
        return this.spawn({
          x: s.x, z: s.z, yaw: s.yaw, type: 'sedan', police: true,
          color: 0xe9ecef, driver: 'ai', aiType: 'police',
        });
      }
    }
    return null;
  }
}

function nearestIndex(lines, v) {
  let best = 0, bd = Infinity;
  for (let i = 0; i < lines.length; i++) {
    const d = Math.abs(lines[i] - v);
    if (d < bd) { bd = d; best = i; }
  }
  return best;
}

export function wrapAngle(a) {
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
}

export function randomColor(rng = Math.random) {
  const palette = [0xd8d8d2, 0x2c3038, 0x8f2c2c, 0x2e5c8a, 0x3e7a4a, 0xc9a33a, 0x6b6f78, 0x9f5a2c, 0xdce4e8, 0x4b3d6b, 0x7a2f4f, 0xbfc6cc];
  return palette[Math.floor(rng() * palette.length)];
}

import * as THREE from 'three';
import { createHuman, animateHuman } from './characters.js';
import { clamp, wrapAngle } from './vehicles.js';

export class Player {
  constructor(game, spawn) {
    this.game = game;
    this.pos = new THREE.Vector3(spawn.x, game.world.groundAt(spawn.x, spawn.z), spawn.z);
    this.vel = new THREE.Vector3();
    this.yaw = spawn.yaw;
    this.cameraYaw = spawn.yaw;
    this.cameraPitch = -0.13;
    this.cameraZoom = 1;
    this.mode = 'foot';
    this.vehicle = null;
    this.onGround = true;
    this.swimming = false;
    this.stepHeight = 0.65;

    this.hp = 100;
    this.maxHp = 100;
    this.armor = 0;
    this.cash = 750;
    this.wanted = 0;
    this.heat = 0;
    this.lastCrime = -999;
    this.ammo = 12;
    this.magSize = 12;
    this.reserve = 96;
    this.weaponName = 'PISTOL';
    this.fireCooldown = 0;
    this.reloadTimer = 0;
    this.aiming = false;
    this.aimBlend = 0;
    this.lastDamage = -999;
    this.invuln = -1;
    this.dead = false;
    this.sprinting = false;
    this.speed = 0;
    this.walkPhase = 0;
    this.shotFlash = 0;

    this.mesh = createHuman({
      armed: true, shirt: 0x2d333f, pants: 0x3b4350, skin: 0xd8a06f, hair: 0x241a13,
    });
    const rig = this.mesh.userData.rig;
    rig.shirtMat.color.setHex(0x2c323d);
    this.mesh.position.copy(this.pos);
    this.mesh.rotation.y = this.yaw;
    game.scene.add(this.mesh);
    this.muzzle = new THREE.Vector3();
  }

  processLook(look, game) {
    const sens = 0.0026;
    if (this.mode === 'vehicle') {
      if (Math.abs(look.x) > 0.01 || Math.abs(look.y) > 0.01) {
        this.cameraYaw -= look.x * sens * 0.9;
        this.cameraPitch -= look.y * 0.0021;
        this.lookHold = 1.1;
      }
    } else {
      this.cameraYaw -= look.x * sens;
      this.cameraPitch -= look.y * 0.0021;
    }
    this.cameraPitch = clamp(this.cameraPitch, -1.05, 0.92);
    if (game.cameraZoomDelta) {
      this.cameraZoom = clamp(this.cameraZoom + game.cameraZoomDelta * 0.1, 0.55, 1.7);
      game.cameraZoomDelta = 0;
    }
  }

  update(dt, game, input) {
    this.aiming = input.aim && this.mode === 'foot';
    this.aimBlend += ((this.aiming ? 1 : 0) - this.aimBlend) * Math.min(1, dt * 12);
    this.fireCooldown = Math.max(0, this.fireCooldown - dt);
    this.shotFlash = Math.max(0, this.shotFlash - dt);
    if (this.invuln > 0) this.invuln -= dt;

    if (this.mode === 'vehicle' && this.vehicle) {
      this.pos.copy(this.vehicle.pos);
      this.mesh.visible = false;
      this.speed = Math.abs(this.vehicle.speed);
      this.sprinting = false;
      if (this.lookHold > 0) this.lookHold -= dt;
      else {
        const diff = wrapAngle(this.vehicle.yaw - this.cameraYaw);
        if (!this.aiming) this.cameraYaw += diff * Math.min(1, dt * 2.0);
      }
      // reload while driving still works
      this.updateReload(dt, game);
      this.updateHealth(dt, game);
      return;
    }

    this.mesh.visible = true;
    const fwd = input.forward;
    const str = input.strafe;
    const mag = Math.min(1, Math.hypot(fwd, str));
    const cy = this.cameraYaw;
    const fx = Math.sin(cy), fz = Math.cos(cy);
    const rx = -Math.cos(cy), rz = Math.sin(cy);
    let dx = fx * fwd + rx * str;
    let dz = fz * fwd + rz * str;
    const dl = Math.hypot(dx, dz);
    if (dl > 1e-4) { dx /= dl; dz /= dl; }

    const wantSprint = input.sprinting && mag > 0.3 && !this.aiming;
    this.sprinting = wantSprint;
    let targetSpeed = this.aiming ? 3.2 : wantSprint ? 9.2 : 5.6;
    if (this.swimming) targetSpeed = 3.2;
    targetSpeed *= mag;
    if (this.invuln > 0) targetSpeed *= 0.6;

    if (mag > 0.02) {
      this.vel.x += (dx * targetSpeed - this.vel.x) * Math.min(1, dt * (this.onGround ? 12 : 3.5));
      this.vel.z += (dz * targetSpeed - this.vel.z) * Math.min(1, dt * (this.onGround ? 12 : 3.5));
      const face = this.aiming ? this.cameraYaw : Math.atan2(dx, dz);
      this.yaw += wrapAngle(face - this.yaw) * Math.min(1, dt * 14);
    } else {
      const fr = Math.max(0, 1 - dt * (this.onGround ? 12 : 1.4));
      this.vel.x *= fr;
      this.vel.z *= fr;
    }
    this.speed = Math.hypot(this.vel.x, this.vel.z);

    const oldX = this.pos.x, oldZ = this.pos.z;
    const oldGround = game.world.groundAt(oldX, oldZ);
    let nx = this.pos.x + this.vel.x * dt;
    let nz = this.pos.z + this.vel.z * dt;

    const ng = game.world.groundAt(nx, nz);
    if (!this.swimming && ng - oldGround > 1.1 && this.pos.y < ng - 0.4) {
      // treat steep risers as walls when walking
      nx = oldX;
      nz = oldZ;
    }
    const fixed = game.world.resolveCircle(nx, nz, 0.42);
    this.pos.x = fixed.x;
    this.pos.z = fixed.z;

    const ground = game.world.groundAt(this.pos.x, this.pos.z);
    this.swimming = ground < -1.1 && this.pos.y < 0.55;
    const inWater = ground < -0.55;

    if (this.swimming) {
      this.onGround = false;
      this.vel.y = 0;
      const bob = Math.sin(game.time * 3.2) * 0.06;
      this.pos.y += (0.25 + bob - this.pos.y) * Math.min(1, dt * 6);
      if (input.jump) this.pos.y += dt * 3.2;
      if (this.pos.y < -0.8) this.takeDamage(6 * dt, game, true);
    } else {
      if (input.jump && this.onGround) {
        this.vel.y = 10.4;
        this.onGround = false;
      }
      this.vel.y -= 27 * dt;
      this.pos.y += this.vel.y * dt;
      if (this.pos.y <= ground + 0.02) {
        this.pos.y = ground + 0.02;
        this.vel.y = 0;
        this.onGround = true;
      } else {
        this.onGround = false;
      }
      if (inWater && this.pos.y < 0.35) {
        // wading
        this.vel.x *= 0.86;
        this.vel.z *= 0.86;
      }
    }

    this.mesh.position.set(this.pos.x, this.pos.y, this.pos.z);
    this.mesh.rotation.y = this.yaw;
    animateHuman(this.mesh, dt, this.speed, { aiming: this.aiming, baseY: this.pos.y });

    this.updateReload(dt, game);
    this.updateHealth(dt, game);
  }

  updateReload(dt, game) {
    if (this.reloadTimer > 0) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) {
        const need = this.magSize - this.ammo;
        const take = Math.min(need, this.reserve);
        this.ammo += take;
        this.reserve -= take;
        game.audio.reload();
      }
    }
  }

  updateHealth(dt, game) {
    if (this.hp < this.maxHp && game.time - this.lastDamage > 5.5) {
      this.hp = Math.min(this.maxHp, this.hp + 2.2 * dt);
    }
    if (this.hp <= 0 && !this.dead) game.killPlayer();
  }

  reload(game) {
    if (this.reloadTimer > 0) return;
    if (this.ammo >= this.magSize || this.reserve <= 0) return;
    this.reloadTimer = 1.15;
    game.audio.reload();
    game.notify('RELOADING', 'Pistol magazine swap', '', 900, true);
  }

  canShoot() {
    return this.mode === 'foot' && !this.dead && this.reloadTimer <= 0 && this.ammo > 0 && this.fireCooldown <= 0;
  }

  consumeShot(game) {
    this.ammo--;
    this.fireCooldown = this.aiming ? 0.2 : 0.26;
    this.shotFlash = 0.06;
    game.audio.gunshot();
    this.mesh.userData.rig.gunTip.getWorldPosition(this.muzzle);
    game.particles.muzzle(this.muzzle);
    game.cameraShake = Math.max(game.cameraShake, 0.18);
    if (this.ammo <= 0 && this.reserve > 0) this.reload(game);
  }

  takeDamage(amount, game, ignoreArmor = false) {
    if (this.dead || this.invuln > 0) return;
    let a = amount;
    if (!ignoreArmor && this.armor > 0) {
      const absorbed = Math.min(this.armor, a * 0.75);
      this.armor -= absorbed;
      a -= absorbed;
    }
    this.hp -= a;
    this.lastDamage = game.time;
    game.hud.damageFlash();
    game.audio.hit();
    if (this.hp <= 0 && !this.dead) game.killPlayer();
  }

  addCash(amount, game) {
    this.cash += amount;
    game.hud.popCash(amount);
  }

  heal(amount, armor = false) {
    if (armor) this.armor = Math.min(100, this.armor + amount);
    else this.hp = Math.min(this.maxHp, this.hp + amount);
  }

  enterVehicle(v, game) {
    this.mode = 'vehicle';
    this.vehicle = v;
    this.mesh.visible = false;
    this.cameraYaw = v.yaw;
    this.cameraPitch = -0.12;
    this.cameraZoom = 1;
    this.pos.copy(v.pos);
    v.enter();
    game.hud.setInVehicle(true);
    game.audio.beep(330, 0.08, 0.1);
  }

  exitVehicle(game) {
    if (!this.vehicle) return;
    const v = this.vehicle;
    const side = new THREE.Vector3(Math.cos(v.yaw), 0, -Math.sin(v.yaw));
    let px = v.pos.x + side.x * 2.2;
    let pz = v.pos.z + side.z * 2.2;
    if (game.world.isBlocked(px, pz, 0.6) || game.world.isWater(px, pz)) {
      px = v.pos.x - side.x * 2.2;
      pz = v.pos.z - side.z * 2.2;
    }
    const fixed = game.world.resolveCircle(px, pz, 0.42);
    this.pos.set(fixed.x, game.world.groundAt(fixed.x, fixed.z) + 0.02, fixed.z);
    this.vel.set(0, 0, 0);
    this.yaw = v.yaw + Math.PI / 2;
    this.cameraYaw = this.yaw;
    this.mode = 'foot';
    this.vehicle = null;
    this.mesh.visible = true;
    this.mesh.position.copy(this.pos);
    v.exit();
    game.hud.setInVehicle(false);
    game.audio.beep(240, 0.08, 0.1);
  }
}

export class CameraRig {
  constructor(game, camera) {
    this.game = game;
    this.camera = camera;
    this.pos = new THREE.Vector3();
    this.lookDir = new THREE.Vector3();
    this.target = new THREE.Vector3();
    this.initialized = false;
    this.fov = 64;
    this._tmp = new THREE.Vector3();
    this._desired = new THREE.Vector3();
    this._shake = new THREE.Vector3();
  }

  update(dt, player) {
    const p = player;
    const cosP = Math.cos(p.cameraPitch);
    this.lookDir.set(
      Math.sin(p.cameraYaw) * cosP,
      Math.sin(p.cameraPitch),
      Math.cos(p.cameraYaw) * cosP
    ).normalize();

    const right = this._tmp.set(-Math.cos(p.cameraYaw), 0, Math.sin(p.cameraYaw));
    const aiming = p.aiming && p.mode === 'foot';
    const shoulder = aiming ? 0.72 : p.mode === 'vehicle' ? 0 : 0.5;
    const baseDist = p.mode === 'vehicle' ? (7.8 + Math.abs(p.vehicle ? p.vehicle.speed : 0) * 0.075) : (aiming ? 2.15 : 4.7);
    const dist = baseDist * p.cameraZoom;
    const targetY = p.mode === 'vehicle' ? 1.65 : 1.55;
    this.target.set(p.pos.x, p.pos.y + targetY, p.pos.z);
    this.target.addScaledVector(right, shoulder);

    this._desired.copy(this.target).addScaledVector(this.lookDir, -dist);
    // Camera obstruction
    if (this.game.world) {
      const dir = this._desired.clone().sub(this.target);
      const len = dir.length();
      if (len > 0.01) {
        dir.normalize();
        const hit = this.game.world.raycastStatic(this.target, dir, len, true);
        const allowed = Math.max(1.0, hit.dist - 0.35);
        if (hit.dist < len) {
          this._desired.copy(this.target).addScaledVector(dir, allowed);
        }
      }
    }

    if (!this.initialized) {
      this.pos.copy(this._desired);
      this.initialized = true;
    } else {
      const k = 1 - Math.exp(-dt * (p.mode === 'vehicle' ? 10 : 15));
      this.pos.lerp(this._desired, k);
    }

    // shake
    const shake = this.game.cameraShake;
    if (shake > 0.001) {
      const s = shake * 0.28;
      this._shake.set((Math.random() - 0.5) * s, (Math.random() - 0.5) * s, (Math.random() - 0.5) * s);
      this.pos.add(this._shake);
      this.game.cameraShake = Math.max(0, shake - dt * 2.4);
    }

    this.camera.position.copy(this.pos);
    const lookTarget = this._tmp.copy(this.target).addScaledVector(this.lookDir, 12);
    this.camera.lookAt(lookTarget);

    const targetFov = p.mode === 'vehicle' ? 70 : aiming ? 52 : 64;
    this.fov += (targetFov - this.fov) * Math.min(1, dt * 8);
    if (Math.abs(this.camera.fov - this.fov) > 0.01) {
      this.camera.fov = this.fov;
      this.camera.updateProjectionMatrix();
    }
  }
}

import * as THREE from 'three';
import { createHuman, animateHuman } from './characters.js';
import { stream, clamp } from './rng.js';
import { wrapAngle } from './vehicles.js';

let pedId = 0;

export class Ped {
  constructor(game, opts = {}) {
    this.game = game;
    this.id = pedId++;
    this.isCop = !!opts.isCop;
    this.pos = new THREE.Vector3(opts.x, game.world.groundAt(opts.x, opts.z), opts.z);
    this.yaw = opts.yaw ?? Math.random() * Math.PI * 2;
    this.hp = 100;
    this.dead = false;
    this.deathTimer = 0;
    this.state = this.isCop ? 'chase' : 'wander';
    this.speed = 0;
    this.target = null;
    this.walkTimer = 0;
    this.shootTimer = Math.random() * 1.2;
    this.stuckTime = 0;
    this.alertTimer = 0;
    this.threat = new THREE.Vector3();
    this.phase = 0;

    this.mesh = createHuman({
      armed: this.isCop,
      cop: this.isCop,
      shirt: this.isCop ? 0x2a3b61 : undefined,
      pants: this.isCop ? 0x202a3d : undefined,
      skin: opts.skin,
      hair: opts.hair,
      shirtColor: opts.shirt,
    });
    if (!this.isCop && opts.shirtColor != null) {
      this.mesh.userData.rig.shirtMat.color.setHex(opts.shirtColor);
    }
    this.mesh.position.copy(this.pos);
    this.mesh.rotation.y = this.yaw;
    game.scene.add(this.mesh);

    this.pickTarget(game);
  }

  get rig() { return this.mesh.userData.rig; }

  pickTarget(game) {
    const city = game.world.city;
    if (this.isCop) {
      this.target = { x: game.player.pos.x, z: game.player.pos.z };
      return;
    }
    let best = null, bd = Infinity;
    for (let i = 0; i < 16; i++) {
      const p = city.walkPoints[Math.floor(Math.random() * city.walkPoints.length)];
      if (!p) continue;
      const d = Math.hypot(p.x - this.pos.x, p.z - this.pos.z);
      if (d > 8 && d < 75 && d < bd) { bd = d; best = p; }
    }
    this.target = best || { x: this.pos.x + 10, z: this.pos.z };
  }

  flee(from, game) {
    const dx = this.pos.x - from.x;
    const dz = this.pos.z - from.z;
    const len = Math.max(1, Math.hypot(dx, dz));
    this.state = 'flee';
    this.alertTimer = 4 + Math.random() * 3;
    this.target = {
      x: this.pos.x + (dx / len) * 32 + (Math.random() - 0.5) * 10,
      z: this.pos.z + (dz / len) * 32 + (Math.random() - 0.5) * 10,
    };
  }

  update(dt, game) {
    if (this.dead) {
      this.deathTimer += dt;
      if (this.deathTimer < 1.2) {
        animateHuman(this.mesh, dt, 0, { dead: true, baseY: game.world.groundAt(this.pos.x, this.pos.z), deadSign: 1 });
      }
      return;
    }

    const player = game.player;
    const distToPlayer = Math.hypot(player.pos.x - this.pos.x, player.pos.z - this.pos.z);

    if (this.isCop) {
      if (game.player.wanted <= 0) {
        this.state = 'leave';
        if (!this.target) this.pickTarget(game);
      } else {
        this.state = 'chase';
      }
    } else if (this.alertTimer > 0) {
      this.alertTimer -= dt;
      if (this.alertTimer <= 0) { this.state = 'wander'; this.pickTarget(game); }
    } else if (player.wanted >= 2 && distToPlayer < 26) {
      if (this.state !== 'flee') this.flee(player.pos, game);
    }

    let targetSpeed = 0;
    if (this.state === 'flee') {
      targetSpeed = 4.8;
    } else if (this.state === 'chase' && this.isCop) {
      const dx = player.pos.x - this.pos.x;
      const dz = player.pos.z - this.pos.z;
      const d = Math.hypot(dx, dz);
      if (d > 13) {
        this.target = { x: player.pos.x, z: player.pos.z };
        targetSpeed = 4.9;
      } else {
        targetSpeed = 0.5;
        this.target = { x: player.pos.x, z: player.pos.z };
        this.tryShoot(dt, game, d);
      }
      // if very far, run
      if (distToPlayer > 100) { this.state = 'leave'; }
    } else if (this.state === 'leave') {
      targetSpeed = 2.4;
      if (!this.target) this.pickTarget(game);
    } else {
      targetSpeed = 1.5 + (this.id % 3) * 0.2;
      if (!this.target) this.pickTarget(game);
    }

    let dx = 0, dz = 0;
    if (this.target) {
      dx = this.target.x - this.pos.x;
      dz = this.target.z - this.pos.z;
      const d = Math.hypot(dx, dz);
      if (d < 1.4 && !this.isCop) {
        this.pickTarget(game);
        this.walkTimer = Math.random() * 3;
      }
    }
    const d = Math.hypot(dx, dz);
    if (d > 0.01) {
      dx /= d; dz /= d;
      const desiredYaw = Math.atan2(dx, dz);
      this.yaw += wrapAngle(desiredYaw - this.yaw) * Math.min(1, dt * 8);
      this.pos.x += dx * targetSpeed * dt;
      this.pos.z += dz * targetSpeed * dt;
      this.speed = targetSpeed;
    } else {
      this.speed = 0;
    }

    // collisions and ground
    const fixed = game.world.resolveCircle(this.pos.x, this.pos.z, 0.36);
    if (Math.abs(fixed.x - this.pos.x) > 0.001 || Math.abs(fixed.z - this.pos.z) > 0.001) {
      this.pos.x = fixed.x;
      this.pos.z = fixed.z;
      this.stuckTime += dt;
      if (this.stuckTime > 0.8) {
        this.pickTarget(game);
        this.stuckTime = 0;
      }
    } else this.stuckTime = 0;
    this.pos.y = game.world.groundAt(this.pos.x, this.pos.z) + 0.02;

    this.mesh.position.set(this.pos.x, this.pos.y, this.pos.z);
    this.mesh.rotation.y = this.yaw;
    const aiming = this.isCop && this.state === 'chase' && this.shootTimer < 0.5;
    animateHuman(this.mesh, dt, this.speed, { aiming, baseY: this.pos.y });

    if (this.isCop && game.player.wanted <= 0 && distToPlayer > 90) {
      this.remove(game);
    }
  }

  tryShoot(dt, game, dist) {
    if (this.state !== 'chase') return;
    this.shootTimer -= dt;
    if (this.shootTimer > 0) return;
    this.shootTimer = 1.4 + Math.random() * 0.7;
    const player = game.player;
    const origin = new THREE.Vector3(this.pos.x, this.pos.y + 1.42, this.pos.z);
    const target = new THREE.Vector3(player.pos.x, player.pos.y + 1.2, player.pos.z);
    const dir = target.clone().sub(origin);
    const len = dir.length();
    dir.normalize();
    const hit = game.world.raycastStatic(origin, dir, len, true);
    if (hit.dist < len - 1.0) return;
    this.rig.gunTip.getWorldPosition(origin);
    game.particles.muzzle(origin);
    game.audio.copShot();
    const hitChance = clamp(0.72 - len / 80, 0.28, 0.7);
    if (Math.random() < hitChance) {
      game.particles.tracer(origin, target, 0xffb0a0);
      player.takeDamage(9 + Math.random() * 7, game);
    } else {
      const miss = target.clone().add(new THREE.Vector3((Math.random() - 0.5) * 3, Math.random() * 2 - 0.5, (Math.random() - 0.5) * 3));
      game.particles.tracer(origin, miss, 0xffb0a0);
    }
    void dist;
  }

  hit(amount, game) {
    if (this.dead) return false;
    this.hp -= amount;
    if (this.hp <= 0) {
      this.die(game);
      return true;
    }
    this.flee(game.player.pos, game);
    if (this.isCop) this.shootTimer = Math.min(this.shootTimer, 0.4);
    return false;
  }

  die(game) {
    this.dead = true;
    this.state = 'dead';
    this.deathTimer = 0;
    this.speed = 0;
    game.particles.blood(new THREE.Vector3(this.pos.x, this.pos.y + 1.0, this.pos.z));
    // drop a few bucks
    if (!this.isCop) {
      const drop = 5 + Math.floor(Math.random() * 35);
      game.spawnCashPickup(this.pos.x, this.pos.z, drop);
    }
    this.mesh.userData.rig.legs.forEach(l => { l.rotation.x = 0; });
  }

  remove(game) {
    game.scene.remove(this.mesh);
    this.removed = true;
  }
}

export class PedManager {
  constructor(game) {
    this.game = game;
    this.list = [];
    this.rng = stream(game.seed, 'peds');
    this.spawnTimer = 0;
    this.copTimer = 0;
    this.copSpawnCooldown = 0;
  }

  spawnCivilian(pos) {
    const city = this.game.world.city;
    let p = pos;
    if (!p) {
      for (let i = 0; i < 20; i++) {
        const c = city.walkPoints[Math.floor(this.rng() * city.walkPoints.length)];
        const d = Math.hypot(c.x - this.game.player.pos.x, c.z - this.game.player.pos.z);
        if (d > 18 && d < 130) { p = c; break; }
      }
    }
    if (!p) return null;
    const ped = new Ped(this.game, {
      x: p.x, z: p.z, yaw: this.rng() * Math.PI * 2,
    });
    this.list.push(ped);
    return ped;
  }

  spawnCop(pos) {
    const city = this.game.world.city;
    let p = pos;
    if (!p) {
      for (let i = 0; i < 30; i++) {
        const c = city.walkPoints[Math.floor(Math.random() * city.walkPoints.length)];
        const d = Math.hypot(c.x - this.game.player.pos.x, c.z - this.game.player.pos.z);
        if (d > 24 && d < 90) { p = c; break; }
      }
    }
    if (!p) {
      const a = Math.random() * Math.PI * 2;
      p = { x: this.game.player.pos.x + Math.cos(a) * 34, z: this.game.player.pos.z + Math.sin(a) * 34 };
    }
    const ped = new Ped(this.game, { x: p.x, z: p.z, isCop: true, yaw: Math.random() * 6.28 });
    this.list.push(ped);
    return ped;
  }

  populate() {
    for (let i = 0; i < 18; i++) this.spawnCivilian();
  }

  update(dt) {
    const game = this.game;
    for (const ped of this.list) {
      if (!ped.removed) ped.update(dt, game);
    }

    // despawn dead / far away peds
    for (const ped of [...this.list]) {
      const far = Math.hypot(ped.pos.x - game.player.pos.x, ped.pos.z - game.player.pos.z) > 260;
      if (ped.removed || (ped.dead && ped.deathTimer > 24) || (far && !ped.isCop)) {
        ped.remove(game);
      }
    }
    this.list = this.list.filter(p => !p.removed);

    // maintain ambient civilians
    this.spawnTimer -= dt;
    if (this.spawnTimer <= 0) {
      this.spawnTimer = 0.7;
      let civilians = 0;
      let cops = 0;
      for (const p of this.list) {
        if (p.dead) continue;
        if (p.isCop) cops++;
        else civilians++;
      }
      if (civilians < 18) this.spawnCivilian();
      const wantCops = game.player.wanted > 0 ? Math.min(8, 1 + game.player.wanted * 2) : 0;
      this.copSpawnCooldown -= dt;
      if (cops < wantCops && this.copSpawnCooldown <= 0) {
        this.copSpawnCooldown = 1.5;
        this.spawnCop();
      }
    }
  }

  alert(pos, radius) {
    for (const p of this.list) {
      if (p.dead || p.isCop) continue;
      if (Math.hypot(p.pos.x - pos.x, p.pos.z - pos.z) < radius) p.flee(pos, this.game);
    }
  }

  raycast(origin, dir, maxDist) {
    let best = null;
    for (const ped of this.list) {
      if (ped.dead) continue;
      // body capsule approximated with two spheres
      const body = new THREE.Vector3(ped.pos.x, ped.pos.y + 1.02, ped.pos.z);
      const head = new THREE.Vector3(ped.pos.x, ped.pos.y + 1.72, ped.pos.z);
      const b = raySphere(origin, dir, body, 0.48, maxDist);
      const h = raySphere(origin, dir, head, 0.3, maxDist);
      let t = null, headshot = false;
      if (b !== null && h !== null) { if (h < b) { t = h; headshot = true; } else t = b; }
      else if (b !== null) t = b;
      else if (h !== null) { t = h; headshot = true; }
      if (t !== null && (!best || t < best.dist)) {
        best = { ped, dist: t, headshot, point: origin.clone().addScaledVector(dir, t) };
      }
    }
    return best;
  }

  nearestCop(pos) {
    let best = null, bd = Infinity;
    for (const p of this.list) {
      if (!p.isCop || p.dead) continue;
      const d = Math.hypot(p.pos.x - pos.x, p.pos.z - pos.z);
      if (d < bd) { bd = d; best = p; }
    }
    return best;
  }

  killFromVehicle(vehicle) {
    if (vehicle.speed < 6) return;
    for (const ped of this.list) {
      if (ped.dead) continue;
      if (Math.hypot(ped.pos.x - vehicle.pos.x, ped.pos.z - vehicle.pos.z) < 2.4) {
        ped.die(this.game);
        this.game.particles.blood(new THREE.Vector3(ped.pos.x, ped.pos.y + 1, ped.pos.z));
        vehicle.speed *= 0.88;
        this.game.registerCrime(ped.isCop ? 3 : 2, 'HIT AND RUN');
        this.game.audio.crash(0.8);
      }
    }
  }

  clear() {
    for (const p of this.list) if (!p.removed) p.remove(this.game);
    this.list = [];
  }
}

function raySphere(origin, dir, center, radius, maxDist) {
  const ox = origin.x - center.x, oy = origin.y - center.y, oz = origin.z - center.z;
  const b = ox * dir.x + oy * dir.y + oz * dir.z;
  const c = ox * ox + oy * oy + oz * oz - radius * radius;
  const disc = b * b - c;
  if (disc < 0) return null;
  const sq = Math.sqrt(disc);
  let t = -b - sq;
  if (t < 0) t = -b + sq;
  if (t < 0 || t > maxDist) return null;
  return t;
}

import * as THREE from 'three';
import { stream } from './rng.js';
import { makePickupMesh } from './characters.js';

export class ItemManager {
  constructor(game) {
    this.game = game;
    this.items = [];
    this.rng = stream(game.seed, 'items');
    this.spawnFixed();
  }

  spawnFixed() {
    const city = this.game.world.city;
    const candidates = city.lots.filter(l => l.type === 'park' || l.type === 'plaza' || l.type === 'parking');
    const used = [];
    const pick = () => {
      for (let i = 0; i < 30; i++) {
        const lot = candidates[Math.floor(this.rng() * candidates.length)];
        if (!lot) continue;
        if (used.some(u => u.x === lot.x && u.z === lot.z)) continue;
        used.push(lot);
        return lot;
      }
      return candidates[0];
    };
    for (let i = 0; i < 5; i++) {
      const lot = pick();
      if (!lot) continue;
      this.add('health', lot.x - 5, lot.z + 5, 50, true);
    }
    for (let i = 0; i < 4; i++) {
      const lot = pick();
      if (!lot) continue;
      this.add('armor', lot.x + 5, lot.z - 5, 60, true);
    }
    for (let i = 0; i < 5; i++) {
      const lot = pick();
      if (!lot) continue;
      this.add('ammo', lot.x + 6, lot.z + 6, 45, true);
    }
  }

  add(kind, x, z, respawn = 0, fixed = false, value = 0) {
    if (this.game.world.isBlocked(x, z, 0.8)) {
      const fixedPos = this.game.world.resolveCircle(x, z, 0.55);
      x = fixedPos.x;
      z = fixedPos.z;
    }
    const mesh = makePickupMesh(kind);
    const y = this.game.world.groundAt(x, z) + 0.24;
    mesh.position.set(x, y, z);
    this.game.scene.add(mesh);
    const item = {
      kind, x, z, y, mesh, active: true, respawn, fixed,
      timer: 0, value, phase: this.rng() * Math.PI * 2,
    };
    this.items.push(item);
    return item;
  }

  spawnCash(x, z, amount) {
    this.add('cash', x, z, 0, false, amount);
  }

  update(dt) {
    const game = this.game;
    const p = game.player.pos;
    for (const item of [...this.items]) {
      if (!item.active) {
        item.timer -= dt;
        if (item.timer <= 0 && item.fixed) {
          item.active = true;
          item.mesh.visible = true;
        } else continue;
      }
      item.phase += dt * 2;
      item.mesh.position.y = item.y + Math.sin(item.phase) * 0.12;
      item.mesh.rotation.y += dt * 1.9;
      const d = Math.hypot(item.x - p.x, item.z - p.z);
      if (d < 1.6 && Math.abs(p.y - item.y) < 2.4) {
        if (item.kind === 'health') {
          if (game.player.hp >= game.player.maxHp) continue;
          game.player.heal(45);
          game.notify('HEALTH', '+45 HP', 'good', 1600, true);
        } else if (item.kind === 'armor') {
          if (game.player.armor >= 100) continue;
          game.player.heal(55, true);
          game.notify('ARMOR', '+55 ARMOR', 'good', 1600, true);
        } else if (item.kind === 'ammo') {
          if (game.player.reserve >= 300) continue;
          game.player.reserve += 36;
          game.notify('AMMO', '+36 PISTOL ROUNDS', 'good', 1600, true);
        } else if (item.kind === 'cash') {
          game.player.addCash(item.value, game);
          game.notify('CASH', `+$${item.value}`, 'good', 1400, true);
        }
        game.audio.pickup();
        item.active = false;
        item.mesh.visible = false;
        item.timer = item.respawn || 0;
        if (!item.fixed) {
          game.scene.remove(item.mesh);
          const idx = this.items.indexOf(item);
          if (idx >= 0) this.items.splice(idx, 1);
        }
      }
    }
  }

  clear() {
    for (const item of this.items) this.game.scene.remove(item.mesh);
    this.items = [];
  }
}

import * as THREE from 'three';
import { stream, clamp } from './rng.js';

const JOB_COLORS = [0xffc72c, 0x62e08a, 0x5ab8ff];
const TYPE_NAMES = ['HOT WHEELS', 'LOOSE ENDS', 'CIRCUIT RUN'];

function makeBeam(color, height = 9, radius = 0.75) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 0.3, side: THREE.DoubleSide, depthWrite: false,
  });
  const beam = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius * 1.15, height, 12, 1, true), mat);
  beam.position.y = height / 2;
  g.add(beam);
  const ringMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, depthWrite: false });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(radius * 1.5, 0.08, 6, 24), ringMat);
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = 0.18;
  g.add(ring);
  const iconMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95 });
  const icon = new THREE.Mesh(new THREE.OctahedronGeometry(0.55, 0), iconMat);
  icon.position.y = height + 0.7;
  g.add(icon);
  g.userData = { beam, ring, icon, mat, ringMat, iconMat, phase: Math.random() * 6 };
  g.renderOrder = 3;
  return g;
}

export class MissionSystem {
  constructor(game) {
    this.game = game;
    this.scene = game.scene;
    this.rng = stream(game.seed, 'missions');
    this.active = null;
    this.jobMarkers = [];
    this.activeMarkers = [];
    this.completed = 0;
    this.jobs = game.world.city.jobPoints.map((pt, i) => ({
      index: i, point: pt, status: 'available', cooldown: 0,
      name: pt.name || TYPE_NAMES[i % TYPE_NAMES.length],
      type: ['delivery', 'hit', 'checkpoints'][i % 3],
      marker: null,
    }));
    for (const job of this.jobs) {
      const m = makeBeam(JOB_COLORS[job.index % JOB_COLORS.length], 7.5, 0.65);
      m.position.set(job.point.x, job.point.y - 0.1, job.point.z);
      this.scene.add(m);
      job.marker = m;
    }
    this.hudDirty = true;
  }

  marker(color, height = 8) {
    const m = makeBeam(color, height, 0.7);
    this.scene.add(m);
    this.activeMarkers.push(m);
    return m;
  }

  clearActiveMarkers() {
    for (const m of this.activeMarkers) this.scene.remove(m);
    this.activeMarkers = [];
  }

  removeMarker(m) {
    if (!m) return;
    this.scene.remove(m);
    const i = this.activeMarkers.indexOf(m);
    if (i >= 0) this.activeMarkers.splice(i, 1);
  }

  update(dt) {
    const game = this.game;
    const t = game.time;
    for (const job of this.jobs) {
      if (job.marker) {
        job.marker.visible = job.status === 'available';
        if (job.marker.visible) {
          job.marker.userData.phase += dt;
          job.marker.userData.icon.rotation.y += dt * 1.8;
          job.marker.userData.ring.rotation.z += dt * 1.2;
          const p = 1 + Math.sin(job.marker.userData.phase * 2.2) * 0.05;
          job.marker.userData.ring.scale.set(p, p, p);
        }
      }
      if (job.status === 'cooldown') {
        job.cooldown -= dt;
        if (job.cooldown <= 0) { job.status = 'available'; this.hudDirty = true; }
      }
    }
    for (const m of this.activeMarkers) {
      const u = m.userData;
      u.phase += dt;
      u.icon.rotation.y += dt * 2.2;
      u.ring.rotation.z -= dt * 1.1;
      const p = 1 + Math.sin(u.phase * 3) * 0.08;
      u.ring.scale.set(p, p, p);
      u.mat.opacity = 0.22 + Math.sin(u.phase * 3) * 0.08;
    }

    const a = this.active;
    if (!a) {
      this.updateAvailablePrompt();
      return;
    }

    // target markers follow their subjects
    if (a.targetVehicle && a.vehicleMarker) {
      if (a.targetVehicle.destroyed) {
        this.fail('TARGET VEHICLE DESTROYED');
        return;
      }
      a.vehicleMarker.position.set(a.targetVehicle.pos.x, a.targetVehicle.pos.y, a.targetVehicle.pos.z);
    }
    if (a.targetPed && a.pedMarker) {
      if (a.targetPed.dead) {
        // completed via onPedKilled normally; this is a safety net
        this.complete();
        return;
      }
      a.pedMarker.position.set(a.targetPed.pos.x, a.targetPed.pos.y, a.targetPed.pos.z);
    }

    a.timer -= dt;
    if (a.timer <= 0) {
      this.fail('OUT OF TIME');
      return;
    }

    if (a.type === 'delivery') {
      if (a.stage === 0) {
        if (game.player.mode === 'vehicle' && game.player.vehicle === a.targetVehicle) {
          a.stage = 1;
          a.objective = 'Deliver the car to the drop-off.';
          this.createDropoff();
          game.notify('JOB UPDATED', 'Delivery point marked', '', 2200);
          this.hudDirty = true;
        }
      } else {
        const p = game.player;
        const d = Math.hypot(p.pos.x - a.dropoff.x, p.pos.z - a.dropoff.z);
        if (p.mode === 'vehicle' && p.vehicle === a.targetVehicle && d < 7) {
          this.complete();
        }
      }
    } else if (a.type === 'hit') {
      if (a.targetPed.dead) this.complete();
    } else if (a.type === 'checkpoints') {
      const cp = a.checkpoints[a.cpIndex];
      if (!cp) { this.complete(); return; }
      if (a.checkpointMarker) {
        a.checkpointMarker.position.set(cp.x, cp.y, cp.z);
      }
      const p = game.player;
      const d = Math.hypot(p.pos.x - cp.x, p.pos.z - cp.z);
      if (d < 7.5) {
        a.cpIndex++;
        game.audio.beep(880, 0.1, 0.12);
        if (a.cpIndex >= a.checkpoints.length) {
          this.complete();
        } else {
          game.notify('CHECKPOINT', `${a.cpIndex}/${a.checkpoints.length}`, 'good', 1400, true);
          this.moveCheckpointMarker();
          this.hudDirty = true;
        }
      }
    }
  }

  updateAvailablePrompt() {
    const game = this.game;
    const p = game.player;
    if (p.mode !== 'foot') return;
    for (const job of this.jobs) {
      if (job.status !== 'available') continue;
      const d = Math.hypot(p.pos.x - job.point.x, p.pos.z - job.point.z);
      if (d < 3.6) {
        game.hud.setPrompt(`<span class="key">E</span> START JOB — ${job.name}`);
        game.hud.setMission(null);
        return;
      }
    }
  }

  canInteract() {
    const game = this.game;
    if (this.active || game.player.mode !== 'foot') return null;
    for (const job of this.jobs) {
      if (job.status !== 'available') continue;
      const d = Math.hypot(game.player.pos.x - job.point.x, game.player.pos.z - job.point.z);
      if (d < 3.6) return job;
    }
    return null;
  }

  interact(job) {
    if (!job) return false;
    const point = job.point;
    if (job.type === 'delivery') this.startDelivery(job);
    else if (job.type === 'hit') this.startHit(job);
    else this.startCheckpoints(job);
    this.game.audio.beep(660, 0.1, 0.12);
    this.hudDirty = true;
    return true;
  }

  pickDropoff(minDist = 70, maxDist = 180) {
    const city = this.game.world.city;
    for (let i = 0; i < 40; i++) {
      const x = city.xLines[2 + Math.floor(this.rng() * 6)];
      const z = city.zLines[2 + Math.floor(this.rng() * 6)];
      const d = Math.hypot(x - this.game.player.pos.x, z - this.game.player.pos.z);
      if (d > minDist && d < maxDist) {
        return { x, z, y: city.groundY + 0.15 };
      }
    }
    return { x: city.cx + 45, z: city.cz - 45, y: city.groundY + 0.15 };
  }

  startDelivery(job) {
    const city = this.game.world.city;
    let spot = null;
    for (let i = 0; i < 40; i++) {
      const s = city.randomRoadSpawn(this.rng);
      const d = Math.hypot(s.x - job.point.x, s.z - job.point.z);
      if (d > 16 && d < 55) { spot = s; break; }
    }
    if (!spot) spot = { x: city.cx + 45, z: city.cz + 15, yaw: 0 };
    const car = this.game.vehicles.spawn({
      x: spot.x, z: spot.z, yaw: spot.yaw,
      type: 'coupe', color: 0xe8b62a, driver: null,
    });
    car.missionTag = 'target';
    const marker = this.marker(0xffc72c, 10);
    const drop = this.pickDropoff(80, 190);
    this.active = {
      type: 'delivery', job, title: 'HOT WHEELS',
      objective: 'Steal the marked yellow car.', timer: 165, maxTimer: 165,
      reward: 1400, stage: 0, targetVehicle: car, vehicleMarker: marker,
      dropoff: drop, dropoffMarker: null,
    };
    this.game.hud.setMission({ kind: 'DELIVERY', title: 'HOT WHEELS', objective: this.active.objective, timer: 165 });
    this.game.notify('JOB ACCEPTED', 'Steal the marked car', '', 2400);
    this.hudDirty = true;
  }

  createDropoff() {
    const a = this.active;
    a.dropoffMarker = this.marker(0x62e08a, 8);
    a.dropoffMarker.position.set(a.dropoff.x, a.dropoff.y - 0.1, a.dropoff.z);
  }

  startHit(job) {
    const city = this.game.world.city;
    let p = null;
    for (let i = 0; i < 30; i++) {
      const c = city.walkPoints[Math.floor(this.rng() * city.walkPoints.length)];
      const d = Math.hypot(c.x - job.point.x, c.z - job.point.z);
      if (d > 55 && d < 145) { p = c; break; }
    }
    if (!p) p = { x: job.point.x + 60, z: job.point.z };
    const ped = this.game.peds.spawnTarget(p);
    if (!ped) { this.game.notify('JOB FAILED', 'No target available', 'bad', 2500); return; }
    const marker = this.marker(0xff4b4b, 8);
    marker.position.set(ped.pos.x, ped.pos.y, ped.pos.z);
    this.active = {
      type: 'hit', job, title: 'LOOSE ENDS',
      objective: 'Eliminate the marked target.', timer: 190, maxTimer: 190,
      reward: 1250, targetPed: ped, pedMarker: marker,
    };
    this.game.hud.setMission({ kind: 'HIT', title: 'LOOSE ENDS', objective: this.active.objective, timer: 190 });
    this.game.notify('CONTRACT', 'Target marked in red', '', 2400);
    this.hudDirty = true;
  }

  startCheckpoints(job) {
    const city = this.game.world.city;
    const pts = [];
    const used = new Set();
    let guard = 0;
    let last = job.point;
    while (pts.length < 4 && guard++ < 100) {
      const ix = 1 + Math.floor(this.rng() * 8);
      const iz = 1 + Math.floor(this.rng() * 8);
      const k = ix + ':' + iz;
      if (used.has(k)) continue;
      used.add(k);
      const x = city.xLines[ix], z = city.zLines[iz];
      if (Math.hypot(x - last.x, z - last.z) < 26) continue;
      pts.push({ x, z, y: city.groundY + 0.15 });
      last = { x, z };
    }
    this.active = {
      type: 'checkpoints', job, title: 'CIRCUIT RUN',
      objective: `Hit checkpoint 1 of ${pts.length}.`, timer: 95, maxTimer: 95,
      reward: 1600, checkpoints: pts, cpIndex: 0, checkpointMarker: null,
    };
    this.moveCheckpointMarker();
    this.game.hud.setMission({ kind: 'RACE', title: 'CIRCUIT RUN', objective: this.active.objective, timer: 95 });
    this.game.notify('RACE STARTED', 'Follow the blue markers', '', 2400);
    this.hudDirty = true;
  }

  moveCheckpointMarker() {
    const a = this.active;
    this.removeMarker(a.checkpointMarker);
    const cp = a.checkpoints[a.cpIndex];
    if (!cp) return;
    a.checkpointMarker = this.marker(0x5ab8ff, 11);
    a.checkpointMarker.position.set(cp.x, cp.y - 0.1, cp.z);
    a.objective = `Hit checkpoint ${a.cpIndex + 1} of ${a.checkpoints.length}.`;
    this.game.hud.setMission({ kind: 'RACE', title: 'CIRCUIT RUN', objective: a.objective, timer: a.timer });
  }

  onVehicleEntered(v) {
    const a = this.active;
    if (!a) return;
    if (a.type === 'delivery' && v === a.targetVehicle && a.stage === 0) {
      a.stage = 1;
      a.objective = 'Deliver the car to the drop-off.';
      this.createDropoff();
      this.game.notify('JOB UPDATED', 'Drop-off marked in green', '', 2400);
      this.hudDirty = true;
    }
  }

  onPedKilled(ped) {
    const a = this.active;
    if (!a || a.type !== 'hit') return;
    if (ped === a.targetPed) this.complete();
  }

  onVehicleDestroyed(v) {
    const a = this.active;
    if (!a) return;
    if (v === a.targetVehicle) this.fail('TARGET VEHICLE DESTROYED');
  }

  complete() {
    const a = this.active;
    if (!a) return;
    const game = this.game;
    this.active = null;
    this.clearActiveMarkers();
    a.job.status = 'cooldown';
    a.job.cooldown = 22;
    a.job.marker.visible = false;
    game.player.addCash(a.reward, game);
    game.audio.missionDone();
    game.notify('JOB COMPLETE', `+$${a.reward.toLocaleString()}`, 'good', 4200);
    game.hud.showBanner('JOB COMPLETE', `+$${a.reward.toLocaleString()}`);
    game.hud.setMission(null);
    game.hud.setPrompt('');
    this.completed++;
    if (a.targetVehicle) a.targetVehicle.missionTag = null;
    if (a.targetPed) a.targetPed.missionTag = null;
    this.hudDirty = true;
  }

  fail(reason = 'JOB FAILED') {
    const a = this.active;
    if (!a) return;
    const game = this.game;
    this.active = null;
    this.clearActiveMarkers();
    a.job.status = 'cooldown';
    a.job.cooldown = 14;
    a.job.marker.visible = false;
    if (a.targetVehicle) a.targetVehicle.missionTag = null;
    if (a.targetPed) a.targetPed.missionTag = null;
    game.audio.fail();
    game.notify('JOB FAILED', reason, 'bad', 4200);
    game.hud.setMission(null);
    game.hud.setPrompt('');
    this.hudDirty = true;
  }

  getMissionInfo() {
    const a = this.active;
    if (!a) return null;
    return { kind: a.type.toUpperCase(), title: a.title, objective: a.objective, timer: a.timer };
  }

  clear() {
    this.clearActiveMarkers();
    for (const j of this.jobs) if (j.marker) this.scene.remove(j.marker);
    this.jobs = [];
    this.active = null;
  }
}

