315: function rayBox(origin, dir, c, maxDist) {
316:   let tmin = 0, tmax = maxDist;
317:   const axes = [
318:     [origin.x, dir.x, c.x0, c.x1],
319:     [origin.y, dir.y, c.y0, c.y1],
320:     [origin.z, dir.z, c.z0, c.z1],
321:   ];
322:   for (const [o, d, min, max] of axes) {
323:     if (Math.abs(d) < 1e-7) {
324:       if (o < min || o > max) return null;
325:     } else {
326:       let t1 = (min - o) / d;
327:       let t2 = (max - o) / d;
328:       if (t1 > t2) { const t = t1; t1 = t2; t2 = t; }
329:       tmin = Math.max(tmin, t1);
330:       tmax = Math.min(tmax, t2);
331:       if (tmin > tmax) return null;
332:     }
333:   }
334:   return tmin >= 0 ? tmin : (tmax >= 0 ? tmax : null);
335: }

